import { createContext, useContext, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Link, Navigate, Route, Routes, useLocation, useParams } from "react-router-dom";
import { components as initialComponents, githubPullRequests, releases as initialReleases, repositoryReadmes, repositoryVerificationRuns, teams as initialTeams } from "./data";
import { id, type ApprovalStatus, type ChangeEvent, type ChangeIntent, type Component, type ComponentChange, type ComponentKind, type GitHubPullRequest, type IntelligenceEvidence, type JevPlanEvaluation, type PlanCandidate, type PlanVersion, type Release, type ReleaseCandidateManifest, type ReleaseIntelligence, type ReleasePlanningPolicy, type ReleaseStatus, type RepositoryReadme, type Resource, type ResourceCalendarWindow, type RiskFinding, type RunbookStep, type SelectedTest, type Team, type TestCaseProposal, type TestGapProposal, type VerificationReview, type VersionTransition } from "./domain";
import { buildReleaseReadModel } from "./planning/releaseReadModel";
import { compileSchedulingModel } from "./planning/schedulingModel";
import { FeatureWorkspace } from "./workbench/FeatureWorkspace";
import { ProductPage, ProductsPage } from "./workbench/ProductsPage";

type Store = {
  teams: Team[]; components: Component[]; releases: Release[];
  setTeams: React.Dispatch<React.SetStateAction<Team[]>>;
  setComponents: React.Dispatch<React.SetStateAction<Component[]>>;
  setReleases: React.Dispatch<React.SetStateAction<Release[]>>;
};
const DataContext = createContext<Store | null>(null);
const useData = () => useContext(DataContext)!;
const statusText: Record<ReleaseStatus, string> = { draft: "下書き", preparing: "準備中", ready: "実行可能", running: "実行中", completed: "完了" };

function useStored<T>(key: string, seed: T) {
  const [value, setValue] = useState<T>(() => { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : seed; } catch { return seed; } });
  useEffect(() => localStorage.setItem(key, JSON.stringify(value)), [key, value]);
  return [value, setValue] as const;
}

export default function App() {
  const [teams, setTeams] = useStored("relay-teams", initialTeams);
  const [components, setComponents] = useStored("relay-components", initialComponents);
  const [releases, setReleases] = useStored("relay-releases", initialReleases);
  const [remoteState, setRemoteState] = useState<"checking" | "local" | "synced">("checking");

  useEffect(() => {
    const controller = new AbortController();
    fetch("/api/state", { signal: controller.signal })
      .then((response) => response.ok ? response.json() : Promise.reject())
      .then((state: { configured?: boolean; hasData?: boolean; teams?: Team[]; components?: Component[]; releases?: Release[] }) => {
        if (!state.configured) { setRemoteState("local"); return; }
        if (state.hasData) {
          setTeams(state.teams ?? []);
          setComponents(state.components ?? []);
          setReleases(state.releases ?? []);
        }
        setRemoteState("synced");
      })
      .catch(() => setRemoteState("local"));
    return () => controller.abort();
  }, [setTeams, setComponents, setReleases]);

  useEffect(() => {
    if (remoteState !== "synced") return;
    const controller = new AbortController();
    const handle = window.setTimeout(() => {
      fetch("/api/state", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ teams, components, releases }), signal: controller.signal }).catch(() => setRemoteState("local"));
    }, 450);
    return () => { controller.abort(); window.clearTimeout(handle); };
  }, [remoteState, teams, components, releases]);

  return <DataContext.Provider value={{ teams, components, releases, setTeams, setComponents, setReleases }}><Layout remoteState={remoteState} /></DataContext.Provider>;
}

function Layout({ remoteState }: { remoteState: "checking" | "local" | "synced" }) {
  const location = useLocation(); const section = location.pathname.split("/")[1] || "releases";
  const [theme, setTheme] = useState(localStorage.getItem("relay-theme") ?? "dark"); document.documentElement.dataset.theme = theme;
  const [jevConfigured, setJevConfigured] = useState<boolean | null>(null);
  useEffect(() => { const controller = new AbortController(); fetch("/api/jev/status", { signal: controller.signal }).then((response) => response.ok ? response.json() : Promise.reject()).then((status: { configured: boolean }) => setJevConfigured(status.configured)).catch(() => setJevConfigured(false)); return () => controller.abort(); }, []);
  const toggleTheme = () => { const next = theme === "dark" ? "light" : "dark"; setTheme(next); localStorage.setItem("relay-theme", next); };
  return <main className="shell"><aside className="rail"><Link className="brand" to="/products"><Logo /><span>Relay</span></Link><nav className="nav" aria-label="Primary navigation"><Nav to="/products" active={section === "products"}>プロダクト</Nav><Nav to="/releases" active={section === "releases"}>リリース</Nav><Nav to="/teams" active={section === "teams"}>チーム</Nav><Nav to="/components" active={section === "components"}>コンポーネント</Nav></nav><div className="rail-bottom"><div className={`jef-presence ${remoteState === "synced" ? "configured" : "unconfigured"}`}><span className="pulse" />{remoteState === "checking" ? "保存先を確認中" : remoteState === "synced" ? "Postgresへ保存中" : "既存画面はローカル保存"}</div><div className={`jef-presence ${jevConfigured ? "configured" : "unconfigured"}`}><span className="pulse" />{jevConfigured === null ? "Jev設定を確認中" : jevConfigured ? "Jev API設定済み" : "Jev API未設定"}</div><div className="account"><span>TK</span><span>Taross K.</span></div></div></aside><section className="workspace"><Header theme={theme} toggle={toggleTheme} /><Routes><Route path="/" element={<Navigate to="/products" replace />} /><Route path="/products" element={<ProductsPage />} /><Route path="/products/:productId" element={<ProductPage />} /><Route path="/products/:productId/features/:featureId" element={<FeatureWorkspace />} /><Route path="/releases" element={<ReleaseList />} /><Route path="/releases/:releaseId" element={<ReleaseRedirect />} /><Route path="/releases/:releaseId/:tab" element={<ReleaseDetail />} /><Route path="/teams" element={<TeamList />} /><Route path="/components" element={<ComponentList />} /><Route path="*" element={<NotFound />} /></Routes></section></main>;
}

function Logo() { return <svg viewBox="0 0 24 24"><path d="M4 4h8v8H4zM12 12h8v8h-8zM12 4h8v8" /></svg>; }
function Nav({ to, active, children }: { to: string; active: boolean; children: ReactNode }) { return <Link to={to} className={`nav-item ${active ? "active" : ""}`} aria-current={active ? "page" : undefined}>{children}</Link>; }
function Header({ theme, toggle }: { theme: string; toggle: () => void }) { const { releases } = useData(); const parts = useLocation().pathname.split("/"); const section = parts[1]; const release = section === "releases" ? releases.find((item) => item.id === parts[2]) : undefined; const title = release?.name ?? (section === "products" ? "プロダクト" : section === "teams" ? "チーム" : section === "components" ? "コンポーネント" : "リリース"); const eyebrow = release?.code ?? (section === "products" ? "Software Delivery Workbench" : section === "teams" ? "組織" : section === "components" ? "プロダクト" : "リリース管理"); return <header className="topbar"><div><span className="eyebrow">{eyebrow}</span><div className="release-title">{title}</div></div><div className="top-actions"><button className="theme-toggle" onClick={toggle}>{theme === "dark" ? "ライト" : "ダーク"}</button>{release && <Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画</Link>}</div></header>; }

function ReleaseList() {
  const data = useData(); const [editing, setEditing] = useState<Release | "new" | null>(null);
  const remove = (release: Release) => confirm(`${release.code}を削除しますか？`) && data.setReleases((items) => items.filter((item) => item.id !== release.id));
  return <section className="collection-view"><CollectionHeader count={data.releases.length} title="リリース" action="リリースを作成" onAction={() => setEditing("new")} /><div className="release-list-head"><span>リリース</span><span>予定日</span><span>責任チーム</span><span>変更</span><span>状態</span><span /></div>{data.releases.map((release) => { const changes = getChanges(release); const names = [...new Set(changes.map((change) => component(data, change.componentId)?.name ?? "削除済み"))]; return <div className="release-list-row" key={release.id}><Link className="release-name" to={`/releases/${release.id}/overview`}><small>{release.code}</small><b>{release.name}</b><em>{names.join("、") || "対象コンポーネント未設定"}</em></Link><span>{dateText(release.scheduledFor)}</span><span>{team(data, release.ownerTeamId)?.name}</span><span>{changes.length}件</span><span className={`release-status ${release.status}`}>{statusText[release.status]}</span><Actions edit={() => setEditing(release)} remove={() => remove(release)} /></div>; })}{editing && <ReleaseForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>;
}

function ReleaseForm({ target, close }: { target?: Release; close: () => void }) {
  const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const next: Release = target ? { ...target, code: str(f, "code"), name: str(f, "name"), scheduledFor: str(f, "date"), ownerTeamId: id(str(f, "team")), status: str(f, "status") as ReleaseStatus } : { id: id(crypto.randomUUID()), code: str(f, "code"), name: str(f, "name"), scheduledFor: str(f, "date"), ownerTeamId: id(str(f, "team")), status: "draft", featureChanges: [], verifications: [] }; data.setReleases((items) => target ? items.map((item) => item.id === target.id ? next : item) : [next, ...items]); close(); };
  return <Dialog title={target ? "リリースを編集" : "リリースを作成"} close={close}><form onSubmit={save}><Input label="リリースID" name="code" value={target?.code} /><Input label="名称" name="name" value={target?.name} /><Input label="予定日" name="date" type="date" value={target?.scheduledFor} /><Choice label="責任チーム" name="team" value={target?.ownerTeamId} options={data.teams.map((item) => [item.id, item.name])} />{target && <Choice label="状態" name="status" value={target.status} options={Object.entries(statusText)} />}<Save /></form></Dialog>;
}

function ReleaseRedirect() { const { releaseId } = useParams(); return <Navigate to={`/releases/${releaseId}/overview`} replace />; }
function ReleaseDetail() { const data = useData(); const { releaseId, tab = "overview" } = useParams(); const release = data.releases.find((item) => item.id === releaseId); if (!release) return <NotFound />; const activeTab = ["overview", "changes", "dependencies", "plan", "runbook", "verification", "approval"].includes(tab) ? tab : "overview"; return <><div className="release-context"><Link to="/releases">← リリース一覧</Link><span>{dateTimeText(release.scheduledAt ?? `${release.scheduledFor}T10:00`)}</span><span>{team(data, release.ownerTeamId)?.name}</span><span className={`release-status ${release.status}`}>{statusText[release.status]}</span></div><nav className="release-tabs"><Tab release={release} name="overview" active={activeTab}>概要</Tab><Tab release={release} name="changes" active={activeTab}>変更</Tab><Tab release={release} name="dependencies" active={activeTab}>依存マップ</Tab><Tab release={release} name="plan" active={activeTab}>実行計画</Tab><Tab release={release} name="runbook" active={activeTab}>手順書</Tab><Tab release={release} name="verification" active={activeTab}>検証</Tab><Tab release={release} name="approval" active={activeTab}>承認・予定</Tab></nav>{activeTab === "overview" ? <ReleaseOverview release={release} /> : activeTab === "changes" ? <Changes release={release} /> : activeTab === "dependencies" ? <DependencyMap release={release} /> : activeTab === "plan" ? <Plan release={release} /> : activeTab === "runbook" ? <Runbook release={release} /> : activeTab === "verification" ? <Verifications release={release} /> : <ApprovalSchedule release={release} />}</>; }
function Tab({ release, name, active, children }: { release: Release; name: string; active: string; children: ReactNode }) { return <Link className={active === name ? "active" : ""} to={`/releases/${release.id}/${name}`}>{children}</Link>; }

function ReleaseOverview({ release }: { release: Release }) {
  const data = useData();
  const changes = getChanges(release);
  const manifest = [...(release.rcManifests ?? [])].reverse().find((item) => item.status !== "superseded");
  const intelligence = release.intelligence;
  const [addingEvent, setAddingEvent] = useState(false);
  const analyze = () => updateRelease(data, release.id, (current) => analyzeRelease(current, data.components));
  const freeze = () => updateRelease(data, release.id, (current) => freezeReleaseCandidate(current, data.components));
  const gateText = intelligence ? ({ unknown: "未評価", blocked: "ブロック", "approval-required": "承認が必要", ready: "リリース可能" } as const)[intelligence.gate.result] : "未評価";
  const readiness = buildReleaseReadModel(release, { teams: data.teams, components: data.components });
  useEffect(() => {
    const evaluations = [...readiness.blockedConditions, ...readiness.unknownConditions, ...readiness.satisfiedConditions];
    if (!evaluations.length) return;
    const controller = new AbortController();
    fetch(`/api/releases/${encodeURIComponent(release.id)}/constraint-evaluations`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ evaluations }), signal: controller.signal }).catch(() => undefined);
    return () => controller.abort();
  }, [release.id, release.planDecision?.graphRevision, release.changeEvents?.length, release.resourceCalendar?.length, release.constraints?.length, release.verifications.length]);
  return <section className="intelligence-view">
    <div className="view-head"><div><span className="eyebrow">Release Train · {release.code}</span><h1>リリース判定概要</h1></div><div className="view-actions"><button className="ghost" onClick={() => setAddingEvent(true)}>不具合・遅延を登録</button><button className="ghost" onClick={analyze}>変更を分析</button><button className="primary" onClick={freeze} disabled={!changes.length || manifest?.status === "frozen"}>{manifest?.status === "frozen" ? "RC固定済み" : "RCを固定"}</button></div></div>
    <div className="intelligence-summary"><div><span>変更</span><b>{changes.length}</b></div><div><span>RC</span><b>{manifest?.status === "frozen" ? "固定済み" : manifest ? "下書き" : "未作成"}</b></div><div><span>Risk</span><b>{highestRisk(intelligence?.risks ?? [])}</b></div><div><span>選択テスト</span><b>{intelligence?.selectedTests.length ?? 0}</b></div><div><span>Release Gate</span><b className={`gate-${intelligence?.gate.result ?? "unknown"}`}>{gateText}</b></div></div>
    <ReleaseLifecyclePanel release={release} readiness={readiness} />
    <ReleaseReadinessPanel release={release} readiness={readiness} />
    <div className="intelligence-grid">
      <section className="intelligence-panel"><header><div><span className="eyebrow">変更の目的と期待動作</span><h2>Change Intent</h2></div><span>{release.changeIntents?.length ?? 0}件</span></header>{(release.changeIntents?.length ? release.changeIntents : inferredIntents(release)).map((intent) => <article className="intent-record" key={intent.id}><b>{intent.title}</b><p>{intent.reason || intent.description}</p><dl><div><dt>期待動作</dt><dd>{intent.expectedBehavior || "未記載"}</dd></div><div><dt>関連Issue</dt><dd>{intent.issueRefs.join("、") || "未登録"}</dd></div><div><dt>申告された影響範囲</dt><dd>{intent.affectedAreas.join("、") || "未登録"}</dd></div></dl></article>)}</section>
      <section className="intelligence-panel"><header><div><span className="eyebrow">検証対象の組み合わせ</span><h2>RC Manifest</h2></div><span>{manifest?.artifacts.length ?? 0}件</span></header>{manifest ? <><div className="manifest-meta"><b>RC #{manifest.sequence}</b><span>{manifest.status === "frozen" ? `固定 ${dateTimeText(manifest.frozenAt!)}` : "下書き"}</span></div>{manifest.artifacts.map((artifact) => <div className="manifest-row" key={artifact.componentId}><b>{component(data, artifact.componentId)?.name}</b><span>{artifact.repository}</span><code>{artifact.version ?? artifact.revision}</code></div>)}</> : <Empty text="RCを固定すると、検証対象のrevisionとbuildをここに記録します。" />}</section>
      <section className="intelligence-panel intelligence-wide"><header><div><span className="eyebrow">Evidenceを参照する推論</span><h2>Risk Assessment</h2></div><span>{intelligence?.risks.length ?? 0}件</span></header>{intelligence?.risks.length ? intelligence.risks.map((risk) => <article className={`risk-record ${risk.level}`} key={risk.id}><span>{risk.level.toUpperCase()}</span><div><b>{risk.reason}</b><small>confidence {Math.round(risk.confidence * 100)}% · Evidence {risk.evidenceIds.join("、")}</small></div></article>) : <Empty text="変更を分析すると、Evidence付きのRiskを表示します。" />}</section>
      <section className="intelligence-panel"><header><div><span className="eyebrow">Policyによる決定</span><h2>Release Gate</h2></div><b className={`gate-${intelligence?.gate.result ?? "unknown"}`}>{gateText}</b></header>{intelligence ? <><ul className="gate-reasons">{intelligence.gate.reasons.map((reason) => <li key={reason}>{reason}</li>)}</ul><small>評価対象: {intelligence.gate.manifestId ?? "RC未固定"} · {dateTimeText(intelligence.gate.evaluatedAt)}</small></> : <Empty text="変更分析とRC固定後にRelease Gateを評価します。" />}</section>
      <section className="intelligence-panel intelligence-wide"><header><div><span className="eyebrow">決定論的に取得した事実</span><h2>Evidence</h2></div><span>{intelligence?.evidence.length ?? 0}件</span></header><div className="evidence-table">{intelligence?.evidence.map((evidence) => <article key={evidence.id}><code>{evidence.id}</code><div><b>{evidence.summary}</b><span>{evidence.details.join("、")}</span></div><small>{evidence.source}</small></article>) ?? <Empty text="変更を分析すると、diff、依存、migration、RCの事実を保存します。" />}</div></section>
    </div>
    {addingEvent && <ChangeEventForm release={release} close={() => setAddingEvent(false)} />}
  </section>;
}

function ReleaseLifecyclePanel({ release, readiness }: { release: Release; readiness: ReturnType<typeof buildReleaseReadModel> }) {
  const phases = releaseLifecycle(release, readiness);
  const current = phases.find((phase) => phase.state === "current") ?? phases.find((phase) => phase.state === "blocked") ?? phases[0];
  const nextActions = releaseNextActions(release, readiness);
  return <section className="lifecycle-panel"><header><div><span className="eyebrow">リリース計画の現在地</span><h2>{current.title}</h2></div><span>{current.summary}</span></header><div className="lifecycle-grid">{phases.map((phase) => <article className={phase.state} key={phase.id}><b>{phase.title}</b><span>{phase.summary}</span><em>{lifecycleStateText[phase.state]}</em></article>)}</div><section className="next-action-list"><header><h3>次にやること</h3><span>{nextActions.length}件</span></header>{nextActions.map((action) => <article key={action.id}><div><b>{action.title}</b><span>{action.detail}</span></div>{action.to ? <Link className="ghost header-link" to={action.to}>{action.label}</Link> : <span>{action.label}</span>}</article>)}</section></section>;
}

const lifecycleStateText = { done: "完了", current: "現在", blocked: "停止中", waiting: "待ち" } as const;

type LifecyclePhase = { id: string; title: string; summary: string; state: keyof typeof lifecycleStateText };
type NextAction = { id: string; title: string; detail: string; label: string; to?: string };

function releaseLifecycle(release: Release, readiness: ReturnType<typeof buildReleaseReadModel>): LifecyclePhase[] {
  const changes = getChanges(release);
  const hasChanges = changes.length > 0;
  const hasCandidate = Boolean(release.planDecision && release.planDecision.graphRevision === graphRevision(release));
  const hasApproved = release.approvalStatus === "approved" || release.approvalStatus === "conditionally-approved";
  const verificationsComplete = release.verifications.length > 0 && release.verifications.every((verification) => verification.status === "passed");
  const hasOpenEvents = Boolean(release.changeEvents?.some((event) => event.status !== "accepted"));
  return [
    { id: "input", title: "計画入力", summary: hasChanges ? `${changes.length}件の変更を登録済み` : "搭載候補が未登録", state: hasChanges ? "done" : "current" },
    { id: "conditions", title: "成立条件", summary: readiness.status === "ready" ? "未確認と違反はありません" : `未確認 ${readiness.unknownConditions.length}件 · 違反 ${readiness.blockedConditions.length}件`, state: readiness.status === "ready" ? "done" : hasChanges ? "current" : "waiting" },
    { id: "plan", title: "計画案", summary: hasCandidate ? "現在の変更に対応する計画候補があります" : "計画候補が未生成または古くなっています", state: hasCandidate ? "done" : readiness.status === "ready" ? "current" : "waiting" },
    { id: "verification", title: "検証", summary: verificationsComplete ? "必要な検証結果を確認済み" : `${release.verifications.length}件の検証項目`, state: verificationsComplete ? "done" : hasCandidate ? "current" : "waiting" },
    { id: "approval", title: "承認", summary: approvalText[release.approvalStatus ?? "not-requested"], state: hasApproved ? "done" : hasOpenEvents ? "blocked" : verificationsComplete ? "current" : "waiting" },
  ];
}

function releaseNextActions(release: Release, readiness: ReturnType<typeof buildReleaseReadModel>): NextAction[] {
  const actions: NextAction[] = [];
  const changes = getChanges(release);
  if (!changes.length) actions.push({ id: "add-change", title: "搭載候補を登録してください", detail: "リリース責任者は、少なくとも1件のコンポーネント変更を登録してください。", label: "変更へ", to: `/releases/${release.id}/changes` });
  if (readiness.unknownConditions.length) actions.push({ id: "confirm-conditions", title: "未確認の成立条件を確認してください", detail: "担当チームは、未確認の前提条件を確認済みの事実または違反として登録してください。", label: "概要で確認" });
  if (readiness.resourceConflicts.length) actions.push({ id: "resolve-resource", title: "担当者・環境の予定競合を解消してください", detail: "リリース責任者は、検証枠を移動するか追加資源を割り当ててください。", label: "実行計画へ", to: `/releases/${release.id}/plan` });
  if (release.changeEvents?.some((event) => event.status !== "accepted")) actions.push({ id: "decide-event", title: "不具合・遅延の対応案を選択してください", detail: "リリース責任者は、修正して再検証、無効化、除外、延期のいずれかを選択してください。", label: "概要で選択" });
  if (changes.length && (!release.planDecision || release.planDecision.graphRevision !== graphRevision(release))) actions.push({ id: "generate-plan", title: "現在の変更で計画候補を生成してください", detail: "成立条件と担当者・環境の予定を反映した計画候補を作成してください。", label: "実行計画へ", to: `/releases/${release.id}/plan` });
  if (release.planDecision && release.verifications.some((verification) => verification.status !== "passed")) actions.push({ id: "complete-verification", title: "必要な検証結果を登録してください", detail: "担当チームは、対象revisionに一致する証跡を登録し、検証結果を確定してください。", label: "検証へ", to: `/releases/${release.id}/verification` });
  if (!actions.length) actions.push({ id: "request-approval", title: "承認申請へ進めます", detail: "リリース責任者は、選択中の計画案と検証結果を確認して承認申請してください。", label: "承認へ", to: `/releases/${release.id}/approval` });
  return actions.slice(0, 4);
}

function ReleaseReadinessPanel({ release, readiness }: { release: Release; readiness: ReturnType<typeof buildReleaseReadModel> }) {
  const data = useData();
  const [addingEvent, setAddingEvent] = useState(false);
  const recordMode = (event: ChangeEvent, selectedMode: NonNullable<ChangeEvent["selectedMode"]>) => updateRelease(data, release.id, (current) => invalidatePlan({
    ...current,
    approvalStatus: ["pending", "approved", "conditionally-approved"].includes(current.approvalStatus ?? "") ? "invalidated" : current.approvalStatus,
    changeEvents: (current.changeEvents ?? []).map((item) => item.id === event.id ? { ...item, selectedMode, status: "accepted" } : item),
    history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "change-event", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "変更イベントの対応案を記録", detail: `${event.summary} · ${releaseUnitModeText[selectedMode]}` }],
  }, "変更イベントの対応案が確定されました。"));
  return <section className={`readiness-panel ${readiness.status}`}>
    <header><div><span className="eyebrow">成立条件・未確認・競合</span><h2>{readiness.status === "ready" ? "この計画は承認前確認へ進めます" : readiness.status === "blocked" ? "この計画はまだ成立していません" : "未確認の前提があります"}</h2></div><div className="readiness-counts"><span>未確認 <b>{readiness.unknownConditions.length}</b></span><span>違反 <b>{readiness.blockedConditions.length}</b></span><span>競合 <b>{readiness.resourceConflicts.length}</b></span></div></header>
    {readiness.approvalInvalidated && <div className="approval-invalidated"><b>承認済みまたは申請中の計画に未反映の変更があります。</b><span>リリース責任者は、対応案を確定してから新しい計画として再承認してください。</span></div>}
    <div className="readiness-grid">
      <section><h3>未確認</h3>{readiness.unknownConditions.length ? readiness.unknownConditions.map((condition) => <article key={condition.constraintId}><b>{condition.explanation}</b><span>{condition.requiredAction}</span></article>) : <p>未確認の成立条件はありません。</p>}</section>
      <section><h3>違反</h3>{readiness.blockedConditions.length ? readiness.blockedConditions.map((condition) => <article key={condition.constraintId}><b>{condition.explanation}</b><span>{condition.requiredAction}</span></article>) : <p>違反している必須条件はありません。</p>}</section>
      <section><h3>競合</h3>{readiness.resourceConflicts.length ? readiness.resourceConflicts.map((conflict) => <article key={`${conflict.resourceId}-${conflict.windowIds.join("-")}`}><b>{conflict.explanation}</b><span>リリース責任者は、検証枠を移動するか追加資源を割り当ててください。</span></article>) : <p>担当者・環境の予定競合はありません。</p>}</section>
    </div>
    <section className="suggested-actions"><header><h3>対応案</h3><button className="ghost" onClick={() => setAddingEvent(true)}>不具合・遅延を登録</button></header>{readiness.suggestedActions.length ? readiness.suggestedActions.map((action) => <article key={action.id}><div><b>{action.label}</b><span>{action.description}</span></div><em>{action.impact}</em></article>) : <p>追加対応はありません。</p>}</section>
    {release.changeEvents?.length ? <section className="change-events"><h3>変更イベント</h3>{release.changeEvents.map((event) => <article key={event.id}><div><span>{changeEventText[event.kind]} · {dateTimeText(event.occurredAt)}</span><b>{event.summary}</b><small>{event.reportedBy}</small></div>{event.status === "accepted" && event.selectedMode ? <em>{releaseUnitModeText[event.selectedMode]}</em> : <div className="mode-actions">{Object.entries(releaseUnitModeText).map(([mode, label]) => <button className="ghost" key={mode} onClick={() => recordMode(event, mode as NonNullable<ChangeEvent["selectedMode"]>)}>{label}</button>)}</div>}</article>)}</section> : null}
    {release.changeEvents?.some((event) => event.status !== "accepted") ? <ReplanOptions events={release.changeEvents.filter((event) => event.status !== "accepted")} /> : null}
    {addingEvent && <ChangeEventForm release={release} close={() => setAddingEvent(false)} />}
  </section>;
}

const releaseUnitModeText: Record<NonNullable<ChangeEvent["selectedMode"]>, string> = { include: "予定通り公開", disable: "含めるが無効化", exclude: "今回から除外", "fix-and-revalidate": "修正して再検証", defer: "次回へ延期" };
const changeEventText: Record<ChangeEvent["kind"], string> = { bug: "不具合", delay: "遅延", "approval-wait": "承認待ち", "environment-failure": "環境障害", "scope-change": "スコープ変更" };

function ReplanOptions({ events }: { events: ChangeEvent[] }) {
  const options: { mode: NonNullable<ChangeEvent["selectedMode"]>; impact: string }[] = [
    { mode: "fix-and-revalidate", impact: "対象変更の修正作業と再検証を追加し、既存計画との差分を最小化します。" },
    { mode: "disable", impact: "成果物に含めたまま公開機能を無効化し、依存先と実行時設定の確認を追加します。" },
    { mode: "exclude", impact: "今回の搭載対象から外し、依存する変更と検証証跡を再評価します。" },
    { mode: "defer", impact: "対象変更を次回リリースへ移し、現在のリリース候補を縮小します。" },
  ];
  return <section className="replan-options"><header><h3>再計画の選択肢</h3><span>{events.length}件の未決定イベント</span></header>{options.map((option) => <article key={option.mode}><b>{releaseUnitModeText[option.mode]}</b><span>{option.impact}</span></article>)}</section>;
}

function ChangeEventForm({ release, close }: { release: Release; close: () => void }) {
  const data = useData();
  const changes = getChanges(release);
  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const componentChangeId = str(form, "componentChangeId");
    const targetChange = changes.find((change) => change.id === componentChangeId);
    const releaseUnit = release.featureChanges.find((feature) => feature.componentChanges.some((change) => change.id === targetChange?.id));
    const next: ChangeEvent = { id: id(crypto.randomUUID()), releaseUnitId: releaseUnit?.id, componentChangeId: targetChange?.id, kind: str(form, "kind") as ChangeEvent["kind"], summary: str(form, "summary"), occurredAt: new Date().toISOString(), reportedBy: str(form, "reportedBy"), status: "open" };
    updateRelease(data, release.id, (current) => invalidatePlan({ ...current, changeEvents: [next, ...(current.changeEvents ?? [])], history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "change-event", occurredAt: next.occurredAt, actor: next.reportedBy, summary: "変更イベントを登録", detail: next.summary }] }, "不具合または遅延が登録されました"));
    close();
  };
  return <Dialog title="不具合・遅延を登録" close={close}><form onSubmit={save}><Choice label="種別" name="kind" options={Object.entries(changeEventText)} /><Choice label="対象変更" name="componentChangeId" options={changes.map((change) => [change.id, `${component(data, change.componentId)?.name} · ${change.summary}`])} /><Input label="内容" name="summary" /><Input label="報告者" name="reportedBy" value="Taross K." /><Save /></form></Dialog>;
}

function Changes({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const groups = groupChanges(data, changes); const [activeId, setActiveId] = useState(changes[0]?.id ?? ""); const [editing, setEditing] = useState<ComponentChange | "new" | null>(null); const [planning, setPlanning] = useState<ComponentChangeGroup | null>(null); const [importing, setImporting] = useState(false); const active = changes.find((item) => item.id === activeId) ?? changes[0];
  const remove = (change: ComponentChange) => { if (!confirm("このコンポーネント変更を削除しますか？")) return; updateRelease(data, release.id, (current) => invalidatePlan({ ...current, featureChanges: current.featureChanges.map((feature) => ({ ...feature, componentChanges: feature.componentChanges.filter((item) => item.id !== change.id) })), verifications: current.verifications.filter((item) => item.componentChangeId !== change.id) }, "コンポーネント変更が削除されました")); };
  return <div className="release-layout"><section className="release-main"><div className="view-head"><div><span className="eyebrow">{groups.length}コンポーネント · {changes.length}変更</span><h1>コンポーネント変更</h1></div><div className="view-actions"><button className="ghost" onClick={() => setImporting(true)}>GitHub PRから取り込む</button><button className="ghost" onClick={() => setEditing("new")}>＋ 変更を追加</button></div></div>{groups.map((group) => { const transition = versionTransition(group.changes[0], group.component, release); return <section className="component-change-group" key={group.component.id}><header><span className={`component-kind kind-${group.component.kind}`}>{group.component.name.slice(0, 1)}</span><div><h2>{group.component.name}</h2><small>{team(data, group.component.ownerTeamId)?.name} · {group.changes.length}変更</small></div><div className="group-version"><b>{transition.currentVersion} → {transition.targetVersion}</b><span>{rolloutText(transition.rollout)} · {coexistenceText(transition.coexistence)}</span><small>{versionSourceText(transition.versionSource)}</small><button onClick={() => setPlanning(group)}>バージョン計画を編集</button></div></header><div className="table-head"><span>変更内容</span><span>PR</span><span>migration</span><span>依存先</span><span>操作</span></div>{group.changes.map((change) => <div className={`release-row ${active?.id === change.id ? "selected" : ""}`} key={change.id} onClick={() => setActiveId(change.id)}><span className="change-cell"><span><b>{change.summary}</b><small>{change.pullRequests[0]?.repository}</small></span></span><span className="mono">#{change.pullRequests[0]?.number ?? "—"}</span><span>{change.migration.required ? change.migration.phase : "なし"}</span><span>{change.dependencyIds.length ? `${change.dependencyIds.length}件` : "なし"}</span><Actions edit={() => setEditing(change)} remove={() => remove(change)} /></div>)}</section>; })}</section>{active ? <ChangeDetail change={active} changes={changes} release={release} /> : <aside className="change-detail"><Empty text="変更がありません" /></aside>}{editing && <ChangeForm release={release} target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}{planning && <ComponentPlanForm release={release} group={planning} close={() => setPlanning(null)} />}{importing && <GitHubImport release={release} close={() => setImporting(false)} />}</div>;
}

function ChangeForm({ release, target, close }: { release: Release; target?: ComponentChange; close: () => void }) {
  const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const selected = data.components.find((item) => item.id === str(f, "component"))!; const next: ComponentChange = { id: target?.id ?? id(crypto.randomUUID()), componentId: selected.id, ownerTeamId: selected.ownerTeamId, summary: str(f, "summary"), pullRequests: [{ repository: selected.repository, number: Number(f.get("pr")), revision: str(f, "revision"), state: "review" }], migration: str(f, "migration") === "none" ? { required: false } : { required: true, phase: str(f, "migration") as "expand" | "migrate" | "contract", execution: str(f, "execution") as "online" | "blocking", backwardCompatible: str(f, "compatible") === "yes" }, maintenance: str(f, "maintenance") as ComponentChange["maintenance"], dependencyIds: Array.from(f.getAll("dependencies")).map((value) => id(String(value))), deploymentWindow: str(f, "window"), recovery: str(f, "recovery") }; updateRelease(data, release.id, (current) => { const features = current.featureChanges.length ? current.featureChanges : [{ id: id<"FeatureChange">("feature-default"), name: current.name, description: "", componentChanges: [] }]; return invalidatePlan({ ...current, featureChanges: features.map((feature, index) => index ? feature : { ...feature, componentChanges: target ? feature.componentChanges.map((item) => item.id === target.id ? next : item) : [...feature.componentChanges, next] }) }, "コンポーネント変更が更新されました"); }); close(); };
  const candidates = getChanges(release).filter((item) => item.id !== target?.id);
  return <Dialog title={target ? "コンポーネント変更を編集" : "コンポーネント変更を追加"} close={close}><form onSubmit={save}><Choice label="コンポーネント" name="component" value={target?.componentId} options={data.components.map((item) => [item.id, item.name])} /><Input label="変更内容" name="summary" value={target?.summary} /><Input label="PR番号" name="pr" type="number" value={String(target?.pullRequests[0]?.number ?? "")} /><Input label="revision" name="revision" value={target?.pullRequests[0]?.revision} /><Choice label="migration" name="migration" value={target?.migration.phase ?? "none"} options={[["none", "なし"], ["expand", "expand"], ["migrate", "migrate"], ["contract", "contract"]]} /><Choice label="実行方式" name="execution" value={target?.migration.execution ?? "online"} options={[["online", "online"], ["blocking", "blocking"]]} /><Choice label="後方互換" name="compatible" value={target?.migration.backwardCompatible ? "yes" : "no"} options={[["yes", "あり"], ["no", "なし"]]} /><Choice label="停止・メンテナンス" name="maintenance" value={target?.maintenance ?? "undetermined"} options={[["none", "不要"], ["maintenance-mode", "メンテナンスモード"], ["service-stop", "サービス停止"], ["undetermined", "未判定"]]} /><label>依存する変更<select name="dependencies" multiple defaultValue={target?.dependencyIds as string[]}>{candidates.map((item) => <option value={item.id} key={item.id}>{component(data, item.componentId)?.name} #{item.pullRequests[0]?.number}</option>)}</select></label><Input label="反映予定" name="window" value={target?.deploymentWindow} /><Input label="回復方法" name="recovery" value={target?.recovery} /><Save /></form></Dialog>;
}

function ComponentPlanForm({ release, group, close }: { release: Release; group: ComponentChangeGroup; close: () => void }) { const data = useData(); const current = versionTransition(group.changes[0], group.component, release); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const rollout = str(f, "rollout") as VersionTransition["rollout"]; const startsAt = str(f, "startsAt"); const expectedCompletionAt = str(f, "expectedCompletionAt"); updateRelease(data, release.id, (target) => invalidatePlan({ ...target, componentPlans: [...(target.componentPlans ?? []).filter((plan) => plan.componentId !== group.component.id), { componentId: group.component.id, currentVersion: str(f, "currentVersion"), targetVersion: str(f, "targetVersion"), versionSource: str(f, "versionSource") as VersionTransition["versionSource"], rollout, startsAt, expectedCompletionAt, coexistence: str(f, "coexistence") as VersionTransition["coexistence"], adoptionMilestones: rolloutMilestones(rollout, startsAt, expectedCompletionAt) }] }, `${group.component.name}のバージョン計画が変更されました`)); close(); }; const identifierLabel = ["backend", "admin"].includes(group.component.kind) ? "revision / artifact" : "アプリバージョン"; return <Dialog title={`${group.component.name}のバージョン計画`} close={close}><form onSubmit={save}><Input label={`現在の${identifierLabel}`} name="currentVersion" value={current.currentVersion} /><Input label={`変更後の${identifierLabel}`} name="targetVersion" value={current.targetVersion} /><Choice label="識別子の取得元" name="versionSource" value={current.versionSource ?? "manual"} options={[["deployment", "デプロイ環境"], ["github", "GitHub Actions artifact"], ["app-store", "App Store Connect"], ["google-play", "Google Play Console"], ["manual", "手入力"]]} /><Choice label="切替方式" name="rollout" value={current.rollout} options={[["immediate", "即時切替"], ["phased", "段階切替"], ["store-phased", "ストア段階配信"]]} /><Choice label="新旧バージョンの共存" name="coexistence" value={current.coexistence} options={[["compatible", "互換性あり"], ["feature-flag", "Feature Flagで制御"], ["incompatible", "共存不可"]]} /><Input label="切替開始" name="startsAt" type="datetime-local" value={current.startsAt} /><Input label="100%到達予定" name="expectedCompletionAt" type="datetime-local" value={current.expectedCompletionAt} /><Save /></form></Dialog>; }

function GitHubImport({ release, close }: { release: Release; close: () => void }) {
  const data = useData(); const changes = getChanges(release); const linked = data.components.filter((item) => item.githubConnection !== "disconnected" && item.repository); const [componentId, setComponentId] = useState<string>(linked[0]?.id ?? ""); const available = githubPullRequests.filter((item) => item.componentId === componentId); const [selectedNumber, setSelectedNumber] = useState<number | null>(available[0]?.number ?? null); const selected = githubPullRequests.find((item) => item.componentId === componentId && item.number === selectedNumber) ?? available[0];
  const chooseComponent = (value: string) => { setComponentId(value); setSelectedNumber(githubPullRequests.find((item) => item.componentId === value)?.number ?? null); };
  const imported = (pr: GitHubPullRequest) => changes.some((change) => change.pullRequests.some((item) => item.repository === pr.repository && item.number === pr.number));
  const add = () => { if (!selected || imported(selected)) return; const migrationRequired = selected.labels.some((label) => label.includes("migration")) || selected.changedFiles.some((file) => file.includes("migrations/")); const dependencyPr = selected.body.match(/#(\d+)/)?.[1]; const dependency = changes.find((change) => change.pullRequests.some((pr) => String(pr.number) === dependencyPr)); const next: ComponentChange = { id: id(crypto.randomUUID()), componentId: selected.componentId, ownerTeamId: component(data, selected.componentId)!.ownerTeamId, summary: selected.title, pullRequests: [{ repository: selected.repository, number: selected.number, revision: selected.revision, state: selected.state, title: selected.title, description: selected.body, author: selected.author, url: `https://github.com/${selected.repository}/pull/${selected.number}`, labels: selected.labels, changedFiles: selected.changedFiles, additions: selected.additions, deletions: selected.deletions }], migration: migrationRequired ? { required: true, phase: selected.labels.includes("expand-migration") ? "expand" : "migrate", execution: selected.labels.includes("blocking-migration") ? "blocking" : "online", backwardCompatible: !selected.labels.includes("breaking-change") } : { required: false }, maintenance: selected.labels.includes("blocking-migration") ? "undetermined" : "none", dependencyIds: dependency ? [dependency.id] : [], deploymentWindow: "未設定", recovery: `GitHub PR #${selected.number}をrevertし、直前revisionへ戻す` }; updateRelease(data, release.id, (current) => invalidatePlan({ ...current, featureChanges: current.featureChanges.map((feature, index) => index === 0 ? { ...feature, componentChanges: [...feature.componentChanges, next] } : feature) }, `GitHub PR #${selected.number}が追加されました`)); close(); };
  const migrationDetected = selected && (selected.labels.some((label) => label.includes("migration")) || selected.changedFiles.some((file) => file.includes("migrations/")));
  return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal github-import"><button className="panel-close" onClick={close}>×</button><header className="import-heading"><span className="demo-badge">GitHubモック · API未接続</span><h2>PRから変更を取り込む</h2><p>コンポーネントに紐付いたリポジトリのPRから、リリース変更の初期値を生成します。</p></header><label className="repo-filter">コンポーネント<select value={componentId} onChange={(event) => chooseComponent(event.target.value)}>{linked.map((item) => <option value={item.id} key={item.id}>{item.name} · {item.repository}</option>)}</select></label><div className="pr-import-layout"><div className="pr-list">{available.map((pr) => <button className={selected?.number === pr.number ? "selected" : ""} onClick={() => setSelectedNumber(pr.number)} key={`${pr.repository}-${pr.number}`}><span><b>#{pr.number} {pr.title}</b><small>{pr.author} · {pr.state === "merged" ? "マージ済み" : pr.state === "draft" ? "下書き" : "レビュー中"}</small></span>{imported(pr) && <em>取込済み</em>}</button>)}</div>{selected && <section className="changelog-preview"><div className="preview-title"><span>生成されるチェンジログ</span><b>{selected.title}</b></div><p>{selected.body}</p><dl><div><dt>リポジトリ / PR</dt><dd>{selected.repository} #{selected.number}</dd></div><div><dt>revision</dt><dd>{selected.revision}</dd></div><div><dt>差分</dt><dd>+{selected.additions} / −{selected.deletions} · {selected.changedFiles.length}ファイル</dd></div><div><dt>migration</dt><dd>{migrationDetected ? "検出あり · onlineとして登録" : "検出なし"}</dd></div><div><dt>停止・メンテナンス</dt><dd>{selected.labels.includes("blocking-migration") ? "要確認" : "不要"}</dd></div></dl><div className="detection-evidence"><b>検出根拠</b><span>{selected.labels.map((label) => <i key={label}>{label}</i>)}</span>{selected.changedFiles.map((file) => <code key={file}>{file}</code>)}</div><button className="primary import-submit" disabled={imported(selected)} onClick={add}>{imported(selected) ? "このPRは取込済み" : "リリース変更として追加"}</button></section>}</div></section></div>;
}

function ChangeDetail({ change, changes, release }: { change: ComponentChange; changes: ComponentChange[]; release: Release }) { const data = useData(); const c = component(data, change.componentId)!; const transition = versionTransition(change, c, release); const pr = change.pullRequests[0]; const deps = change.dependencyIds.map((dep) => changes.find((item) => item.id === dep)).filter(Boolean).map((item) => component(data, item!.componentId)?.name).join("、") || "なし"; return <aside className="change-detail"><span className="eyebrow">{c.name} · {team(data, change.ownerTeamId)?.name}</span><h2>{change.summary}</h2><div className="pr-link">{pr?.repository} #{pr?.number} · {pr?.revision}</div><section className="version-transition-summary"><span>バージョン遷移</span><b>{transition.currentVersion} → {transition.targetVersion}</b><small>{dateTimeText(transition.startsAt)}開始 · {dateTimeText(transition.expectedCompletionAt)}到達予定</small><em className={`coexistence ${transition.coexistence}`}>{coexistenceText(transition.coexistence)}</em></section>{pr?.description && <section className="recorded-changelog"><span>PRチェンジログ</span><p>{pr.description}</p><div><b>差分</b><em>+{pr.additions} / −{pr.deletions} · {pr.changedFiles?.length ?? 0}ファイル</em></div>{pr.labels && <div className="recorded-labels">{pr.labels.map((label) => <i key={label}>{label}</i>)}</div>}</section>}<dl className="change-facts"><Fact name="migration" value={change.migration.required ? `${change.migration.phase} · ${change.migration.execution}` : "なし"} /><Fact name="停止・メンテナンス" value={maintenanceText(change.maintenance)} /><Fact name="依存する変更" value={deps} /><Fact name="反映予定" value={change.deploymentWindow} /><Fact name="回復方法" value={change.recovery} wide /></dl></aside>; }
function Fact({ name, value, wide }: { name: string; value: string; wide?: boolean }) { return <div className={wide ? "wide" : ""}><dt>{name}</dt><dd>{value}</dd></div>; }

function DependencyMap({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const groups = groupChanges(data, changes); const stages = buildComponentStages(groups); const byChange = new Map(changes.map((change) => [change.id, change])); const dependencyCount = changes.reduce((sum, change) => sum + change.dependencyIds.length, 0);
  return <section className="dependency-view"><div className="view-head"><div><span className="eyebrow">{groups.length}コンポーネント · {changes.length}変更</span><h1>依存マップ</h1></div><div className="view-summary">変更間依存 {dependencyCount}件 · 実行段階 {stages.length}</div></div><div className="dependency-flow">{stages.map((stage, stageIndex) => <section className="dependency-stage" key={stageIndex}><header><span>実行段階 {stageIndex + 1}</span><b>{stageIndex === 0 ? "先行条件なし" : `段階 ${stageIndex} の完了後`}</b></header><div className="dependency-stage-items">{stage.map((group) => { const transition = versionTransition(group.changes[0], group.component, release); return <article className="dependency-component" key={group.component.id}><header><div><b>{group.component.name}</b><span>{team(data, group.component.ownerTeamId)?.name}</span></div><code>{transition.currentVersion} → {transition.targetVersion}</code></header><div className="dependency-change-list">{group.changes.map((change) => { const pr = hydratedPullRequest(change); const dependencies = change.dependencyIds.map((dependencyId) => byChange.get(dependencyId)).filter(Boolean); return <section key={change.id}><header><div><span>PR #{pr?.number ?? "—"}</span><b>{change.summary}</b></div><em>{pr?.state === "merged" ? "マージ済み" : pr?.state === "draft" ? "下書き" : "レビュー中"}</em></header><div className="change-scope"><span>{pr?.changedFiles?.length ?? 0}ファイル</span><span>+{pr?.additions ?? 0} / −{pr?.deletions ?? 0}</span>{change.migration.required && <span>{change.migration.phase} migration</span>}</div><div className="changed-file-list">{pr?.changedFiles?.map((file) => <code key={file}>{file}</code>) ?? <span>変更ファイル情報なし</span>}</div>{dependencies.length > 0 && <div className="dependency-requirement"><span>先行変更</span>{dependencies.map((dependency) => <b key={dependency!.id}>{component(data, dependency!.componentId)?.name} · PR #{dependency!.pullRequests[0]?.number} · {dependency!.summary}</b>)}</div>}</section>; })}</div><footer><span>{rolloutText(transition.rollout)}</span><span>{coexistenceText(transition.coexistence)}</span><span>{dateTimeText(transition.startsAt)}開始</span></footer></article>; })}</div></section>)}</div></section>;
}

function Plan({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const groups = groupChanges(data, changes); const [planning, setPlanning] = useState<ComponentChangeGroup | null>(null); const [addingEvent, setAddingEvent] = useState(false); const transitions = groups.map((group) => ({ group, transition: versionTransition(group.changes[0], group.component, release) })); const risks = releasePlanRisks(data, release, groups); const readiness = buildReleaseReadModel(release, { teams: data.teams, components: data.components }); const range = timelineRange(transitions.map((item) => item.transition)); const ticks = Array.from({ length: 6 }, (_, index) => new Date(range.start + ((range.end - range.start) * index) / 5)); const mobileCompletion = Math.max(...transitions.filter((item) => ["ios", "android"].includes(item.group.component.kind)).map((item) => new Date(item.transition.expectedCompletionAt).getTime()), 0); const contractAfter = new Date(mobileCompletion + 24 * 60 * 60 * 1000);
  return <section className="plan-view"><div className="view-head"><div><span className="eyebrow">コンポーネント別バージョン遷移</span><h1>実行計画</h1></div><div className="view-actions"><button className="ghost" onClick={() => setAddingEvent(true)}>不具合・遅延を登録</button><div className="view-summary">{groups.length}コンポーネント · 新旧共存 {transitions.filter((item) => item.transition.rollout !== "immediate").length}件 · リスク {risks.length}件</div></div></div><PlanVersionStrip release={release} /><PlanDecisionPanel release={release} /><ResourceCalendarPanel release={release} conflicts={readiness.resourceConflicts} /><div className="plan-layout timeline-plan"><div className="version-timeline"><div className="timeline-axis"><span>コンポーネント</span><div>{ticks.map((tick) => <time key={tick.toISOString()}>{shortDateTime(tick)}</time>)}</div></div>{transitions.map(({ group, transition }) => <TimelineLane key={group.component.id} component={group.component} changes={group.changes} transition={transition} range={range} edit={() => setPlanning(group)} />)}{mobileCompletion > 0 && <section className="compatibility-gate"><b>互換性維持期間</b><span>バックエンドの旧APIとexpand schemaは、モバイルの100%到達予定である{dateTimeText(new Date(mobileCompletion).toISOString())}まで維持します。</span><em>contract migration: {dateText(contractAfter.toISOString().slice(0, 10))}以降</em></section>}</div><aside className="risk-panel"><span className="eyebrow">計画上のリスク</span><h2>{risks.length}件</h2>{risks.map((risk, index) => <div className={`risk-item ${risk.level}`} key={`${risk.title}-${index}`}><span>{risk.level === "high" ? "高" : risk.level === "medium" ? "中" : "低"}</span><div><small>{risk.scope}</small><b>{risk.title}</b><p>{risk.body}</p><em>{risk.control}</em></div></div>)}<div className="release-policy"><b>計画判定</b><span>{risks.some((risk) => risk.level === "high") ? "条件付き" : "実行可能"}</span></div></aside></div>{planning && <ComponentPlanForm release={release} group={planning} close={() => setPlanning(null)} />}{addingEvent && <ChangeEventForm release={release} close={() => setAddingEvent(false)} />}</section>;
}

function PlanVersionStrip({ release }: { release: Release }) {
  const versions = [...(release.planVersions ?? [])].sort((left, right) => right.sequence - left.sequence);
  if (!versions.length) return <section className="plan-version-strip"><span className="eyebrow">Plan Version</span><p>計画候補を生成すると、承認可能な計画バージョンをここに記録します。</p></section>;
  return <section className="plan-version-strip"><span className="eyebrow">Plan Version</span><div>{versions.slice(0, 4).map((version) => <article className={version.status} key={version.id}><b>v{version.sequence}</b><span>{planVersionStatusText[version.status]}</span><em>{version.graphRevision}</em><small>{dateTimeText(version.createdAt)}</small></article>)}</div></section>;
}

const planVersionStatusText: Record<PlanVersion["status"], string> = { draft: "下書き", candidate: "候補", approved: "承認済み", superseded: "置換済み" };

function ResourceCalendarPanel({ release, conflicts }: { release: Release; conflicts: ReturnType<typeof buildReleaseReadModel>["resourceConflicts"] }) {
  const resources = release.resources ?? [];
  const windows = [...(release.resourceCalendar ?? [])].sort((left, right) => new Date(left.start).getTime() - new Date(right.start).getTime());
  const [adding, setAdding] = useState(false);
  const [addingResource, setAddingResource] = useState(false);
  const schedulingModel = compileSchedulingModel(release);
  if (!resources.length && !windows.length) return <section className="resource-calendar-panel"><header><div><span className="eyebrow">担当者・環境の予定</span><h2>検証枠はまだ登録されていません</h2></div><div className="resource-calendar-actions"><button className="ghost" onClick={() => setAddingResource(true)}>担当者・環境を追加</button><button className="ghost" onClick={() => setAdding(true)} disabled={!resources.length}>検証枠を追加</button></div></header><p>QA担当者、環境、端末などの利用可能時間を登録すると、競合を検出できます。</p>{addingResource && <ResourceForm release={release} close={() => setAddingResource(false)} />}{adding && <ResourceWindowForm release={release} close={() => setAdding(false)} />}</section>;
  return <section className="resource-calendar-panel"><header><div><span className="eyebrow">担当者・環境の予定</span><h2>{conflicts.length ? "検証枠に競合があります" : "検証枠は成立しています"}</h2></div><div className="resource-calendar-actions"><span>{resources.length}資源 · {windows.length}予約</span><button className="ghost" onClick={() => setAddingResource(true)}>担当者・環境を追加</button><button className="ghost" onClick={() => setAdding(true)}>検証枠を追加</button></div></header>{conflicts.length > 0 && <div className="resource-conflict-list">{conflicts.map((conflict) => <p key={`${conflict.resourceId}-${conflict.windowIds.join("-")}`}>{conflict.explanation}</p>)}</div>}<div className="resource-calendar-grid">{resources.map((resource) => <article key={resource.id}><header><b>{resource.name}</b><span>利用可能枠 {resource.capacity}</span></header>{windows.filter((window) => window.resourceId === resource.id).map((window) => <div className={conflicts.some((conflict) => conflict.windowIds.includes(window.id)) ? "conflicting" : ""} key={window.id}><b>{window.label}</b><span>{shortDateTime(new Date(window.start))} → {shortDateTime(new Date(window.end))}</span><em>{window.fixed ? "固定" : "移動可"}</em></div>)}</article>)}</div><section className="scheduling-model-summary"><h3>計算用モデル</h3><p>これはsolver実行結果ではありません。変更、検証、担当者・環境の予定を計算しやすい形に正規化した入力です。</p><div><span>作業 {schedulingModel.activities.length}</span><span>資源 {schedulingModel.resources.length}</span><span>固定予定 {schedulingModel.calendar.filter((window) => window.fixed).length}</span></div></section>{addingResource && <ResourceForm release={release} close={() => setAddingResource(false)} />}{adding && <ResourceWindowForm release={release} close={() => setAdding(false)} />}</section>;
}

function ResourceForm({ release, close }: { release: Release; close: () => void }) {
  const data = useData();
  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const next: Resource = { id: id(crypto.randomUUID()), name: str(form, "name"), kind: str(form, "kind") as Resource["kind"], ownerTeamId: str(form, "team") ? id(str(form, "team")) : undefined, capacity: Number(form.get("capacity") ?? 1) };
    updateRelease(data, release.id, (current) => ({ ...current, resources: [...(current.resources ?? []), next], history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "schedule", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "担当者・環境を追加", detail: `${next.name} · 利用可能枠 ${next.capacity}` }] }));
    close();
  };
  return <Dialog title="担当者・環境を追加" close={close}><form onSubmit={save}><Input label="名称" name="name" /><Choice label="種別" name="kind" options={[["person", "担当者"], ["team-capacity", "チーム枠"], ["environment", "QA環境"], ["device", "検証端末"], ["external-review", "外部審査枠"]]} /><Choice label="管理チーム" name="team" options={data.teams.map((team) => [team.id, team.name])} /><Input label="利用可能枠" name="capacity" type="number" value="1" /><Save /></form></Dialog>;
}

function ResourceWindowForm({ release, close }: { release: Release; close: () => void }) {
  const data = useData();
  const resources = release.resources ?? [];
  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const next: ResourceCalendarWindow = {
      id: id(crypto.randomUUID()),
      resourceId: id(str(form, "resourceId")),
      label: str(form, "label"),
      start: str(form, "start"),
      end: str(form, "end"),
      capacityUsed: Number(form.get("capacityUsed") ?? 1),
      fixed: form.get("fixed") === "on",
    };
    updateRelease(data, release.id, (current) => invalidatePlan({ ...current, resourceCalendar: [...(current.resourceCalendar ?? []), next], history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "schedule", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "検証枠を追加", detail: `${next.label} · ${dateTimeText(next.start)} - ${dateTimeText(next.end)}` }] }, "担当者・環境の予定が変更されました"));
    close();
  };
  return <Dialog title="検証枠を追加" close={close}><form onSubmit={save}><Choice label="担当者・環境" name="resourceId" options={resources.map((resource) => [resource.id, resource.name])} /><Input label="予定名" name="label" /><Input label="開始" name="start" type="datetime-local" value={release.scheduledAt ?? `${release.scheduledFor}T10:00`} /><Input label="終了" name="end" type="datetime-local" value={release.scheduledAt ?? `${release.scheduledFor}T11:00`} /><Input label="使用枠" name="capacityUsed" type="number" value="1" /><label className="history-option"><input name="fixed" type="checkbox" /><span><b>この予定を固定する</b><small>固定済みの検証枠は再計画時に動かさない前提として扱います。</small></span></label><Save /></form></Dialog>;
}

function PlanDecisionPanel({ release }: { release: Release }) {
  const data = useData();
  const policy = releasePlanningPolicy(release);
  const currentRevision = graphRevision(release);
  const decision = release.planDecision;
  const stale = Boolean(decision && decision.graphRevision !== currentRevision);
  const [editingPolicy, setEditingPolicy] = useState(false);
  const [evaluating, setEvaluating] = useState(false);
  const [evaluationError, setEvaluationError] = useState("");
  const generate = () => {
    const result = derivePlanCandidates(data, release);
    if (!result.candidates.length) { setEvaluationError("候補を生成するには、コンポーネント変更を1件以上登録してください。"); return; }
    updateRelease(data, release.id, (current) => {
      const sequence = Math.max(0, ...(current.planVersions ?? []).map((version) => version.sequence)) + 1;
      const version: PlanVersion = { id: id(crypto.randomUUID()), releaseId: current.id, sequence, graphRevision: currentRevision, status: "candidate", createdAt: new Date().toISOString(), basedOnVersionId: [...(current.planVersions ?? [])].reverse().find((item) => item.status === "approved")?.id, changeSummary: `${result.candidates.length}件の計画候補を生成` };
      return {
        ...current,
        approvalStatus: ["approved", "conditionally-approved", "pending"].includes(current.approvalStatus ?? "") ? "invalidated" : current.approvalStatus,
        approvedPlanRevision: undefined,
        planVersions: [...(current.planVersions ?? []).map((item) => item.status === "candidate" ? { ...item, status: "superseded" as const } : item), version],
        planDecision: { graphRevision: currentRevision, generatedAt: version.createdAt, ...result, selectedPlanId: result.candidates[0].id },
        history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "plan", occurredAt: version.createdAt, actor: "System", summary: "判断基準と依存マップから実行計画候補を生成", detail: `${result.candidates.length}候補 · ${currentRevision} · PlanVersion ${sequence}` }],
      };
    });
  };
  const select = (candidateId: string) => updateRelease(data, release.id, (current) => {
    if (!current.planDecision || current.planDecision.selectedPlanId === candidateId) return current;
    return { ...current, approvalStatus: ["approved", "conditionally-approved", "pending"].includes(current.approvalStatus ?? "") ? "invalidated" : current.approvalStatus, approvedPlanRevision: undefined, planDecision: { ...current.planDecision, selectedPlanId: candidateId, evaluation: undefined }, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "plan", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "実行計画候補を変更", detail: current.planDecision.candidates.find((candidate) => candidate.id === candidateId)?.name }] };
  });
  const evaluate = async () => {
    if (!decision || stale || evaluating) return;
    setEvaluating(true); setEvaluationError("");
    try {
      const evaluation = await requestJevPlanEvaluation(release, decision.candidates);
      updateRelease(data, release.id, (current) => ({ ...current, planDecision: current.planDecision ? { ...current.planDecision, selectedPlanId: evaluation.selectedPlanId, evaluation } : current.planDecision, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "jev", occurredAt: evaluation.evaluatedAt, actor: "Jev API", summary: "判断基準に対して実行計画を評価", detail: recommendationText(evaluation.recommendation) + " · リスク " + evaluation.riskScore.toFixed(1) + "/5 · confidence " + Math.round(evaluation.confidence * 100) + "%" }] }));
    } catch (error) { setEvaluationError(error instanceof Error ? error.message : "Jev評価に失敗しました。"); }
    finally { setEvaluating(false); }
  };
  return <section className="plan-decision-panel">
    <header><div><span className="eyebrow">判断基準と依存マップから生成</span><h2>計画候補とJev評価</h2></div><div className="plan-decision-actions"><code>{currentRevision}</code><button className="ghost" onClick={() => setEditingPolicy(true)}>判断基準を編集</button><button className="ghost" onClick={generate}>{decision ? "計画候補を再生成" : "計画候補を生成"}</button>{decision && !stale && <button className="primary" onClick={evaluate} disabled={evaluating}>{evaluating ? "Jev APIで評価中" : "Jev APIで評価"}</button>}</div></header>
    <dl className="planning-policy-summary"><div><dt>優先事項</dt><dd>{planningPriorityText[policy.priority]}</dd></div><div><dt>目的</dt><dd>{policy.objective}</dd></div><div><dt>後方互換</dt><dd>{policy.requireBackwardCompatibility ? "必須" : "必須ではない"}</dd></div><div><dt>承認単位の分割</dt><dd>{policy.allowSplit ? "許可" : "許可しない"}</dd></div>{policy.deadline && <div><dt>完了目標</dt><dd>{dateTimeText(policy.deadline)}</dd></div>}</dl>
    {evaluationError && <div className="stale-plan"><b>計画候補またはJev評価を更新できませんでした</b><span>{evaluationError}</span></div>}
    {stale && <div className="stale-plan"><b>判断基準、依存マップ、または予定が変更されています</b><span>以前の計画候補とJev評価は承認に利用できません。候補を再生成してください。</span></div>}
    {!decision && <p className="plan-empty">判断基準、依存関係、migration、バージョン切替から実行可能な候補を生成します。</p>}
    {decision && !stale && <><div className="plan-candidates">{decision.candidates.map((candidate) => <button className={decision.selectedPlanId === candidate.id ? "selected" : ""} onClick={() => select(candidate.id)} key={candidate.id}><header><b>{candidate.name}</b><span>総合リスク {candidate.deterministicRisk.toFixed(1)}</span></header><p>{candidate.summary}</p><dl><div><dt>目的適合</dt><dd>{candidate.metrics?.objectiveFit ?? "—"}/5</dd></div><div><dt>調整コスト</dt><dd>{candidate.metrics?.coordinationCost ?? "—"}/5</dd></div></dl><small>{dateTimeText(candidate.estimatedCompletionAt)} 完了見込</small><em>{candidateConstraints(candidate).length}件の制約</em></button>)}</div>{Boolean(decision.excludedCandidates?.length) && <section className="excluded-plans"><h3>生成しなかった候補</h3>{decision.excludedCandidates!.map((candidate) => <p key={candidate.name}><b>{candidate.name}</b><span>{candidate.reason}</span></p>)}</section>}</>}
    {decision?.evaluation && !stale && <div className="jev-plan-result"><span className="demo-badge">Jev API · {decision.evaluation.provider?.model ?? "旧評価"}</span><b>{recommendationText(decision.evaluation.recommendation)}</b><p>選択: {decision.candidates.find((candidate) => candidate.id === decision.evaluation?.selectedPlanId)?.name} · リスク {decision.evaluation.riskScore}/5 · confidence {Math.round(decision.evaluation.confidence * 100)}%</p><div>{Object.entries(decision.evaluation.categories).map(([key, value]) => <span key={key}>{riskCategoryText[key] ?? key} {value.toFixed(1)}</span>)}</div><h3>運用上の制約</h3><ul>{evaluationCommitments(decision.evaluation, decision.candidates.find((candidate) => candidate.id === decision.evaluation?.selectedPlanId)).map((commitment) => <li key={commitment}>{commitment}</li>)}</ul></div>}
    {editingPolicy && <PlanningPolicyForm release={release} close={() => setEditingPolicy(false)} />}
  </section>;
}

const planningPriorityText: Record<ReleasePlanningPolicy["priority"], string> = { balanced: "均衡", deadline: "期限", compatibility: "互換性", continuity: "継続運用", coordination: "調整コスト" };

function PlanningPolicyForm({ release, close }: { release: Release; close: () => void }) {
  const data = useData(); const policy = releasePlanningPolicy(release);
  const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const next: ReleasePlanningPolicy = { priority: str(form, "priority") as ReleasePlanningPolicy["priority"], objective: str(form, "objective"), deadline: str(form, "deadline") || undefined, requireBackwardCompatibility: form.get("requireBackwardCompatibility") === "on", allowSplit: form.get("allowSplit") === "on" }; updateRelease(data, release.id, (current) => invalidatePlan({ ...current, planningPolicy: next }, "実行計画の判断基準が変更されました。")); close(); };
  return <Dialog title="実行計画の判断基準" close={close}><form onSubmit={save}><Choice label="最優先する事項" name="priority" value={policy.priority} options={Object.entries(planningPriorityText)} /><Input label="計画の目的" name="objective" value={policy.objective} /><label>完了目標<input name="deadline" type="datetime-local" defaultValue={policy.deadline ?? ""} /></label><label className="policy-checkbox"><input type="checkbox" name="requireBackwardCompatibility" defaultChecked={policy.requireBackwardCompatibility} /><span><b>後方互換を必須にする</b><small>旧版クライアントが稼働中でも利用できる候補だけを生成します。</small></span></label><label className="policy-checkbox"><input type="checkbox" name="allowSplit" defaultChecked={policy.allowSplit} /><span><b>承認単位の分割を許可する</b><small>無効にすると、分割リリースは候補に含めません。</small></span></label><Save /></form></Dialog>;
}

const runbookPhaseText: Record<RunbookStep["phase"], string> = { precheck: "実行前確認", migration: "migration", deploy: "反映", verify: "検証", rollout: "段階配信", close: "完了判定" };

function Runbook({ release }: { release: Release }) {
  const data = useData(); const revision = graphRevision(release); const decision = release.planDecision; const evaluated = decision?.graphRevision === revision && decision.evaluation?.selectedPlanId === decision.selectedPlanId; const selectedPlan = decision?.candidates.find((candidate) => candidate.id === decision.selectedPlanId); const runbook = release.runbook; const current = Boolean(runbook && runbook.graphRevision === revision && runbook.planId === decision?.selectedPlanId); const componentIds = new Set(getChanges(release).map((change) => change.componentId)); const readmes = repositoryReadmes.filter((readme) => componentIds.has(readme.componentId));
  const generate = () => { if (!decision || !evaluated) return; const steps = generateRunbookSteps(data, release, readmes); updateRelease(data, release.id, (target) => ({ ...target, runbook: { graphRevision: revision, planId: decision.selectedPlanId, generatedAt: new Date().toISOString(), mock: true, sourceDocuments: readmes.map(({ repository, path, revision: sourceRevision }) => ({ repository, path, revision: sourceRevision })), steps }, history: [...releaseHistory(target), { id: id(crypto.randomUUID()), type: "runbook", occurredAt: new Date().toISOString(), actor: "System", summary: "リリース手順書を生成", detail: `${selectedPlan?.name} · ${readmes.length} README · ${steps.length}手順` }] })); };
  return <section className="runbook-view"><div className="view-head"><div><span className="eyebrow">{revision}{selectedPlan ? ` · ${selectedPlan.name}` : ""}</span><h1>リリース手順書</h1></div><div className="view-actions"><span className="demo-badge">ローカル生成</span><button className="primary" disabled={!evaluated} onClick={generate}>{runbook ? "手順書を再生成" : "手順書を生成"}</button></div></div>{!evaluated && <section className="runbook-gate"><div><b>現在の実行計画に対するJev評価が必要です</b><span>依存マップから計画候補を生成し、Jev APIで評価すると手順書を生成できます。</span></div><Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画へ</Link></section>}{runbook && !current && <section className="stale-plan runbook-stale"><b>この手順書は現在の計画と一致しません</b><span>依存マップ、予定、または選択した計画が変更されています。実行には使用せず、Jev評価後に再生成してください。</span></section>}{runbook && current && <div className="runbook-layout"><div className="runbook-steps"><header><div><span className="eyebrow">生成日時</span><b>{dateTimeText(runbook.generatedAt)}</b></div><span>{runbook.steps.length}手順</span></header>{runbook.steps.map((step) => { const target = step.componentId ? component(data, step.componentId) : undefined; const owner = target ? team(data, target.ownerTeamId) : undefined; return <article className="runbook-step" key={step.id}><div className="runbook-order">{String(step.order).padStart(2, "0")}</div><div><header><span>{runbookPhaseText[step.phase]}</span>{target && <em>{target.name} · {owner?.name}</em>}</header><h2>{step.title}</h2><p>{step.instruction}</p>{step.command && <div className="runbook-command"><span>README記載コマンド</span><code>{step.command}</code></div>}<dl><div><dt>期待結果</dt><dd>{step.expectedResult}</dd></div>{step.stopCondition && <div><dt>中止条件</dt><dd>{step.stopCondition}</dd></div>}{step.recovery && <div><dt>復旧方法</dt><dd>{step.recovery}</dd></div>}</dl><footer>{step.sourceRefs.map((source) => <span key={source}>{source}</span>)}</footer></div></article>; })}</div><aside className="runbook-sources"><span className="eyebrow">参照したREADMEモック</span><h2>{runbook.sourceDocuments.length}リポジトリ</h2><p>実際のGitHub APIには未接続です。以下の固定スナップショットを参照しています。</p>{readmes.map((readme) => <details open key={readme.repository}><summary><b>{readme.repository}</b><span>{readme.path} · {readme.revision}</span></summary><p>{readme.summary}</p><ul>{readme.cautions.map((caution) => <li key={caution}>{caution}</li>)}</ul></details>)}</aside></div>}{!runbook && evaluated && <section className="runbook-empty"><b>手順書はまだ生成されていません</b><span>{readmes.length}件のREADMEモック、コンポーネント変更、検証項目、選択した実行計画を入力として生成します。</span></section>}</section>;
}
function TimelineLane({ component: target, changes, transition, range, edit }: { component: Component; changes: ComponentChange[]; transition: VersionTransition; range: { start: number; end: number }; edit?: () => void }) { const start = percentAt(transition.startsAt, range); const end = percentAt(transition.expectedCompletionAt, range); return <article className={`timeline-lane kind-${target.kind}`}><header><b>{target.name}</b><span>{transition.currentVersion} → {transition.targetVersion}</span><small>{versionSourceText(transition.versionSource)} · {changes.map((change) => `#${change.pullRequests[0]?.number}`).join(" · ")}</small>{edit && <button onClick={edit}>バージョン計画を編集</button>}</header><div className="lane-track"><div className="old-version" style={{ width: `${start}%` }}><span>{transition.currentVersion}</span></div><div className={`rollout-window ${transition.rollout}`} style={{ left: `${start}%`, width: `${Math.max(end - start, transition.rollout === "immediate" ? .3 : 1.5)}%` }}><b>{rolloutText(transition.rollout)}</b><small>{coexistenceText(transition.coexistence)}</small></div><div className="target-version" style={{ left: `${end}%` }}><span>{transition.targetVersion}</span></div>{transition.adoptionMilestones.filter((milestone) => milestone.percentage < 100).map((milestone) => <i className="milestone" style={{ left: `${percentAt(milestone.at, range)}%` }} key={`${milestone.at}-${milestone.percentage}`}><span>{milestone.percentage}%</span></i>)}</div><footer><span>{dateTimeText(transition.startsAt)} 切替開始</span><span>{dateTimeText(transition.expectedCompletionAt)} 100%到達予定</span></footer></article>; }

function Verifications({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const [section, setSection] = useState<"plan" | "proposals" | "evidence">("plan"); const [addingChangelog, setAddingChangelog] = useState(false); const [addingEvidence, setAddingEvidence] = useState(false); const [editingPlan, setEditingPlan] = useState(false); const [reviewing, setReviewing] = useState(false); const [reviewError, setReviewError] = useState("");
  const assessments = release.verifications.map((verification) => ({ verification, assessment: verificationAssessment(release, verification) }));
  const sufficient = assessments.filter(({ assessment }) => assessment.state === "sufficient").length;
  const extract = () => updateRelease(data, release.id, (current) => ({ ...current, verifications: current.verifications.map((verification) => { const change = getChanges(current).find((item) => item.id === verification.componentChangeId); const pullRequest = change?.pullRequests[0]; if (!pullRequest) return verification; const existing = verification.evidence ?? []; const imported = repositoryVerificationRuns.filter((run) => run.repository === pullRequest.repository && run.revision === pullRequest.revision && !existing.some((item) => item.url === run.url)).map((run) => ({ ...run, id: id<"VerificationEvidence">(crypto.randomUUID()), source: run.type === "build" ? "github-release" as const : "github-actions" as const })); const next = { ...verification, evidence: [...existing, ...imported] }; return { ...next, status: verificationAssessment(current, next).state === "sufficient" ? "passed" : "running" }; }), history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "verification", occurredAt: new Date().toISOString(), actor: "GitHub", summary: "リポジトリの検証証跡を取得", detail: "対象revisionに実在するGitHub ActionsとGitHub Releaseの記録を取り込みました。" }] }));
  const acceptProposal = (proposalId: string) => updateRelease(data, release.id, (current) => { if (!current.intelligence) return current; const proposal = current.intelligence.testGapProposals?.find((item) => item.id === proposalId); if (!proposal || proposal.status === "accepted") return current; const selected: SelectedTest = { id: `TEST-PROPOSAL-${proposal.id}`, name: proposal.suggestedTestName, category: "functional", level: proposal.suggestedLevel, required: true, reason: `Test Gap提案を承認: ${proposal.reason}`, evidenceIds: proposal.evidenceIds }; return { ...current, intelligence: { ...current.intelligence, selectedTests: [...current.intelligence.selectedTests, selected], testGapProposals: current.intelligence.testGapProposals.map((item) => item.id === proposalId ? { ...item, status: "accepted" } : item) } }; });
  const acceptCase = (caseId: string) => updateRelease(data, release.id, (current) => { if (!current.intelligence) return current; const testCase = current.intelligence.testCaseProposals?.find((item) => item.id === caseId); if (!testCase || testCase.status === "accepted") return current; const selected: SelectedTest = { id: `TEST-CASE-${testCase.id}`, name: testCase.name, category: testCase.category, level: testCase.level, required: true, reason: `具体テストケースを採用: ${testCase.reason}`, evidenceIds: testCase.evidenceIds }; return { ...current, intelligence: { ...current.intelligence, selectedTests: [...current.intelligence.selectedTests, selected], testCaseProposals: current.intelligence.testCaseProposals.map((item) => item.id === caseId ? { ...item, status: "accepted" } : item) } }; });
  const runCase = (caseId: string) => updateRelease(data, release.id, (current) => { if (!current.intelligence) return current; const testCase = current.intelligence.testCaseProposals?.find((item) => item.id === caseId); if (!testCase) return current; const executedAt = new Date().toISOString(); const runId = `RUN-${crypto.randomUUID().slice(0, 8)}`; const assertions = testCase.executable.steps.flatMap((step) => step.assertions.map((assertion) => ({ label: `${step.driver}.${assertion.actualPath} ${assertion.operator}`, passed: true, actual: assertion.expected, expected: assertion.expected }))); const run = { id: runId, result: "passed" as const, executedAt, assertions }; const runEvidence: IntelligenceEvidence = { id: id<"IntelligenceEvidence">(`EV-${runId}`), type: "test-result", subjectId: testCase.id, summary: `${testCase.name}のモック実行結果: 成功`, details: assertions.map((item) => `${item.label}: PASS`), source: `local-mock-runner/${runId}`, observedAt: executedAt }; return { ...current, intelligence: { ...current.intelligence, evidence: [...current.intelligence.evidence.filter((item) => item.subjectId !== testCase.id || item.type !== "test-result"), runEvidence], testCaseProposals: current.intelligence.testCaseProposals.map((item) => item.id === caseId ? { ...item, lastRun: run } : item) } }; });
  const review = async () => { setReviewing(true); setReviewError(""); try { const result = await requestVerificationReview(release); updateRelease(data, release.id, (current) => ({ ...current, verificationReview: result, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "verification", occurredAt: result.evaluatedAt, actor: "Jev API", summary: "検証計画とチェンジログの整合性を評価", detail: `${verificationReviewText[result.verdict]} · confidence ${Math.round(result.confidence * 100)}%` }] })); } catch (error) { setReviewError(error instanceof Error ? error.message : "Jev評価に失敗しました。"); } finally { setReviewing(false); } };
  return <section className="work-view verification-view">
    <div className="view-head"><div><span className="eyebrow">{sufficient}/{release.verifications.length}件で実施結果を確認</span><h1>検証</h1></div><div className="view-actions">{section === "plan" && <><button className="ghost" onClick={() => setEditingPlan(true)}>検証方法を編集</button><button className="ghost" onClick={() => setAddingChangelog(true)}>チェンジログを記載</button><button className="primary" onClick={review} disabled={reviewing}>{reviewing ? "Jev APIで評価中" : "検証計画を評価"}</button></>}{section === "evidence" && <><span className="demo-badge">GitHub取得モック</span><button className="ghost" onClick={extract}>実行結果を取り込む</button><button className="primary" onClick={() => setAddingEvidence(true)}>手動結果を登録</button></>}</div></div>
    {reviewError && <div className="stale-plan verification-review"><b>検証計画を評価できませんでした</b><span>{reviewError}</span></div>}
    {release.verificationReview && <section className={`verification-review-result ${release.verificationReview.verdict}`}><div><span className="eyebrow">Jev API · {release.verificationReview.provider?.model ?? "評価結果"}</span><b>{verificationReviewText[release.verificationReview.verdict]}</b></div><span>confidence {Math.round(release.verificationReview.confidence * 100)}% · {dateTimeText(release.verificationReview.evaluatedAt)}</span></section>}
    <nav className="verification-sections" aria-label="検証ビュー"><button className={section === "plan" ? "active" : ""} onClick={() => setSection("plan")}>検証計画</button><button className={section === "proposals" ? "active" : ""} onClick={() => setSection("proposals")}>テスト提案 <span>{(release.intelligence?.testGapProposals?.filter((item) => item.status === "proposed").length ?? 0) + (release.intelligence?.testCaseProposals?.filter((item) => item.status === "proposed").length ?? 0)}</span></button><button className={section === "evidence" ? "active" : ""} onClick={() => setSection("evidence")}>証跡 <span>{release.verifications.flatMap((item) => item.evidence ?? []).length}</span></button></nav>
    <div className="verification-summary"><div><span>検証項目</span><b>{release.verifications.length}</b></div><div><span>結果確認済み</span><b>{sufficient}</b></div><div><span>未確認</span><b>{assessments.filter(({ assessment }) => assessment.state === "insufficient").length}</b></div><div><span>失敗・不一致</span><b>{assessments.filter(({ assessment }) => ["failed", "revision-mismatch", "expired"].includes(assessment.state)).length}</b></div></div>
    {section === "plan" && <div className="verification-workspace plan-only"><div className="verification-requirements">{assessments.map(({ verification, assessment }) => { const change = changes.find((item) => item.id === verification.componentChangeId); const target = change && component(data, change.componentId); const changelog = release.changelogs?.find((item) => item.componentChangeId === change?.id); return <article className="verification-card" key={verification.id}><header><div><span>{target?.name} · {change?.pullRequests[0]?.repository}@{change?.pullRequests[0]?.revision}</span><h2>{verification.name}</h2></div><b className={`evidence-state ${assessment.state}`}>{verificationAssessmentText[assessment.state]}</b></header><dl><div><dt>検証方法</dt><dd>{verification.method ?? "担当チームは、このリリースで実施する検証方法を登録してください。"}</dd></div><div><dt>成功条件</dt><dd>{verification.successCriteria ?? "担当チームは、判定可能な成功条件を登録してください。"}</dd></div><div><dt>実施条件</dt><dd>{verification.condition}</dd></div><div><dt>担当</dt><dd>{team(data, verification.ownerTeamId)?.name}</dd></div></dl><section className="evidence-coverage"><h3>このリリースで必要と定義した証跡</h3>{verificationEvidenceTypes(verification).length ? verificationEvidenceTypes(verification).map((type) => { const evidence = assessment.validEvidence.find((item) => item.type === type); return <div key={type}><b>{verificationEvidenceTypeText[type]}</b><span>{evidence ? `${evidence.name} · ${dateTimeText(evidence.observedAt)}` : "対象revisionの証跡がありません。"}</span><em>{evidence ? "確認済み" : "未確認"}</em></div>; }) : <p>担当チームは、この検証の結果を何で確認するか定義してください。</p>}</section>{assessment.reasons.length > 0 && <ul className="evidence-reasons">{assessment.reasons.map((reason) => <li key={reason}>{reason}</li>)}</ul>}{changelog ? <section className="verification-changelog"><span>{changelog.source === "github-release" ? "GitHub Release" : "手書き"} · {changelog.author}</span><b>{changelog.summary}</b><p>{changelog.impact}</p><dl><div><dt>互換性</dt><dd>{changelog.compatibility}</dd></div><div><dt>想定した検証</dt><dd>{changelog.expectedVerification}</dd></div></dl></section> : <p className="missing-changelog">担当チームは、この変更の影響と想定する検証をチェンジログに記載してください。</p>}</article>; })}</div></div>}
    {section === "proposals" && <TestProposalWorkspace release={release} accept={acceptProposal} acceptCase={acceptCase} runCase={runCase} />}
    {section === "evidence" && <EvidenceWorkspace release={release} />}
    {editingPlan && <VerificationPlanForm release={release} close={() => setEditingPlan(false)} />}{addingChangelog && <ChangelogForm release={release} close={() => setAddingChangelog(false)} />}{addingEvidence && <ManualEvidenceForm release={release} close={() => setAddingEvidence(false)} />}
  </section>;
}

const testCategoryText: Record<SelectedTest["category"], string> = { smoke: "Smoke Test", "critical-journey": "Critical Journey", functional: "Functional Test", regression: "Regression Test", "incident-regression": "Incident Regression", contract: "Contract Test", model: "Model / State Test", resilience: "Resilience Test" };
function TestProposalWorkspace({ release, accept, acceptCase, runCase }: { release: Release; accept: (proposalId: string) => void; acceptCase: (caseId: string) => void; runCase: (caseId: string) => void }) {
  const intelligence = release.intelligence; if (!intelligence) return <div className="verification-empty"><b>変更分析が必要です</b><span>概要で変更を分析すると、変更差分、依存、migrationからテスト区分と不足ケースを提案します。</span><Link className="ghost header-link" to={`/releases/${release.id}/overview`}>概要へ</Link></div>;
  return <div className="test-planning-workspace"><section className="test-case-plan"><header><div><span className="eyebrow">fixture・driver command・assertion</span><h2>実行可能テスト仕様</h2></div><b>{intelligence.testCaseProposals?.filter((item) => item.status === "proposed").length ?? 0}件未採用</b></header><div className="test-case-list">{intelligence.testCaseProposals?.map((testCase) => <article className={testCase.status} key={testCase.id}><header><div><span>{testCategoryText[testCase.category]} · {testCase.level}</span><h3>{testCase.name}</h3></div><div className="test-case-actions"><button className="ghost" onClick={() => runCase(testCase.id)}>モック実行</button><button className={testCase.status === "accepted" ? "ghost" : "primary"} disabled={testCase.status === "accepted"} onClick={() => acceptCase(testCase.id)}>{testCase.status === "accepted" ? "選択済み" : "仕様を採用"}</button></div></header><div className="executable-steps">{testCase.executable.steps.map((step, index) => <section key={`${step.driver}-${index}`}><header><b>{index + 1}. {step.driver}</b><code>{step.command}</code></header><dl><div><dt>Input</dt><dd><pre>{JSON.stringify(step.input, null, 2)}</pre></dd></div><div><dt>Assertions</dt><dd>{step.assertions.map((assertion) => <code key={assertion.actualPath}>{assertion.actualPath} {assertion.operator} {JSON.stringify(assertion.expected)}</code>)}</dd></div></dl></section>)}</div><details className="test-fixture"><summary>Fixture</summary><pre>{JSON.stringify(testCase.executable.fixture, null, 2)}</pre></details>{testCase.lastRun && <section className={`test-run-result ${testCase.lastRun.result}`}><header><b>{testCase.lastRun.result === "passed" ? "PASS" : "FAIL"}</b><span>{testCase.lastRun.id} · {dateTimeText(testCase.lastRun.executedAt)}</span></header>{testCase.lastRun.assertions.map((assertion) => <p key={assertion.label}><span>{assertion.passed ? "✓" : "×"}</span><code>{assertion.label}</code><em>actual {JSON.stringify(assertion.actual)}</em></p>)}</section>}<footer><span>選択根拠: {testCase.reason}</span><small>Evidence: {testCase.evidenceIds.join("、")}</small></footer></article>)}</div></section><section className="selected-test-plan"><header><div><span className="eyebrow">今回実行するテスト</span><h2>Test Selection</h2></div><b>{intelligence.selectedTests.length}件</b></header>{Object.entries(testCategoryText).map(([category, label]) => { const tests = intelligence.selectedTests.filter((test) => test.category === category); return tests.length ? <section className="test-category" key={category}><header><b>{label}</b><span>{tests.length}件</span></header>{tests.map((test) => <article key={test.id}><div><b>{test.name}</b><span>{test.level}</span></div><p>{test.reason}</p><small>Evidence: {test.evidenceIds.join("、") || "全Trainで必須"}</small></article>)}</section> : null; })}</section><section className="test-gap-plan"><header><div><span className="eyebrow">不足Propertyと推奨レイヤー</span><h2>Test Gap</h2></div><b>{intelligence.testGapProposals?.filter((item) => item.status === "proposed").length ?? 0}件未承認</b></header>{intelligence.testGapProposals?.map((proposal) => <article className={`test-proposal ${proposal.status}`} key={proposal.id}><div><b>{proposal.property}</b><span>{proposal.currentCoverage}</span></div><p>{proposal.reason}</p><footer><span>推奨: {proposal.suggestedLevel} · {proposal.suggestedTestName}</span><button className={proposal.status === "accepted" ? "ghost" : "primary"} disabled={proposal.status === "accepted"} onClick={() => accept(proposal.id)}>{proposal.status === "accepted" ? "選択済み" : "提案を採用"}</button></footer></article>)}</section></div>;
}
function EvidenceWorkspace({ release }: { release: Release }) {
  const records = release.verifications.flatMap((verification) => (verification.evidence ?? []).map((evidence) => ({ evidence, verification }))); const localRuns = release.intelligence?.evidence.filter((item) => item.type === "test-result") ?? []; return <div className="evidence-workspace"><header><div><span className="eyebrow">RC revisionと検証結果の照合</span><h2>検証証跡</h2></div><b>{records.length + localRuns.length}件</b></header>{localRuns.length > 0 && <section className="local-run-evidence"><h3>ローカルモック実行</h3>{localRuns.map((run) => <article key={run.id}><div><b>{run.summary}</b><span>{run.source}</span></div><code>{run.id}</code><small>{dateTimeText(run.observedAt)}</small></article>)}</section>}{records.length ? <div className="evidence-record-list">{records.map(({ evidence, verification }) => <article key={evidence.id}><header><div><b>{evidence.name}</b><span>{verification.name}</span></div><em className={evidence.result}>{evidence.result === "passed" ? "成功" : "失敗"}</em></header><dl><div><dt>種別</dt><dd>{verificationEvidenceTypeText[evidence.type]}</dd></div><div><dt>対象revision</dt><dd><code>{evidence.repository}@{evidence.revision}</code></dd></div><div><dt>取得元</dt><dd>{evidence.source}</dd></div><div><dt>確認時刻</dt><dd>{dateTimeText(evidence.observedAt)}</dd></div></dl>{evidence.url && <a href={evidence.url} target="_blank" rel="noreferrer">証跡を開く</a>}</article>)}</div> : !localRuns.length && <Empty text="対象RCに紐付いた検証証跡はまだありません。実行結果を取り込むか、手動結果を登録してください。" />}</div>;
}

type VerificationAssessmentState = "sufficient" | "insufficient" | "failed" | "revision-mismatch" | "expired";
const verificationAssessmentText: Record<VerificationAssessmentState, string> = { sufficient: "結果確認済み", insufficient: "結果未確認", failed: "検証失敗", "revision-mismatch": "revision不一致", expired: "証跡期限切れ" };
const verificationEvidenceTypeText = { unit: "unit test", integration: "integration test", e2e: "E2E", contract: "API契約テスト", migration: "migration検証", build: "build・artifact", security: "security scan", manual: "手動確認" } as const;
function verificationEvidenceTypes(verification: Release["verifications"][number]) { return verification.requiredEvidenceTypes ?? []; }
function verificationAssessment(release: Release, verification: Release["verifications"][number]) {
  const change = getChanges(release).find((item) => item.id === verification.componentChangeId); const revision = change?.pullRequests[0]?.revision; const evidence = verification.evidence ?? []; const now = Date.now(); const validEvidence = evidence.filter((item) => item.revision === revision && (!item.expiresAt || new Date(item.expiresAt).getTime() >= now) && item.result === "passed"); const required = verificationEvidenceTypes(verification); const reasons: string[] = [];
  const failed = evidence.some((item) => item.revision === revision && item.result === "failed"); const expired = evidence.some((item) => item.revision === revision && item.expiresAt && new Date(item.expiresAt).getTime() < now); const mismatch = evidence.length > 0 && !evidence.some((item) => item.revision === revision); const missing = required.filter((type) => !validEvidence.some((item) => item.type === type));
  if (!verification.method) reasons.push("担当チームは、このリリースで実施する検証方法を登録してください。"); if (!verification.successCriteria) reasons.push("担当チームは、この検証の成功条件を登録してください。"); if (!required.length) reasons.push("担当チームは、この検証で必要な証跡を定義してください。"); if (failed) reasons.push("対象revisionに失敗した検証の証跡があります。"); if (expired) reasons.push("対象revisionの検証証跡が有効期限を過ぎています。"); if (mismatch) reasons.push("取得した証跡のrevisionがリリース対象と一致しません。"); if (missing.length) reasons.push(`担当チームは、${missing.map((type) => verificationEvidenceTypeText[type]).join("、")}の証跡を登録してください。`);
  const definitionMissing = !verification.method || !verification.successCriteria || !required.length; const state: VerificationAssessmentState = failed ? "failed" : expired ? "expired" : mismatch ? "revision-mismatch" : definitionMissing || missing.length ? "insufficient" : "sufficient"; return { state, reasons, validEvidence };
}

function VerificationPlanForm({ release, close }: { release: Release; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const verificationId = str(form, "verification"); updateRelease(data, release.id, (current) => ({ ...current, verifications: current.verifications.map((verification) => verification.id === verificationId ? { ...verification, method: str(form, "method"), successCriteria: str(form, "successCriteria"), condition: str(form, "condition"), requiredEvidenceTypes: form.getAll("recordTypes") as Release["verifications"][number]["requiredEvidenceTypes"], status: "pending", evidence: [] } : verification) })); close(); }; return <Dialog title="検証方法を編集" close={close}><form onSubmit={save}><Choice label="検証項目" name="verification" options={release.verifications.map((item) => [item.id, item.name])} /><Input label="検証方法" name="method" /><Input label="成功条件" name="successCriteria" /><Input label="実施条件" name="condition" /><fieldset className="verification-record-options"><legend>このリリースで必要な証跡</legend>{Object.entries(verificationEvidenceTypeText).map(([key, label]) => <label key={key}><input type="checkbox" name="recordTypes" value={key} /><span>{label}</span></label>)}</fieldset><Save /></form></Dialog>; }

function ChangelogForm({ release, close }: { release: Release; close: () => void }) { const data = useData(); const changes = getChanges(release); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const componentChangeId = id<"ComponentChange">(str(form, "change")); const entry = { id: id<"ReleaseChangelog">(crypto.randomUUID()), componentChangeId, source: str(form, "source") as "github-release" | "manual", summary: str(form, "summary"), impact: str(form, "impact"), compatibility: str(form, "compatibility"), expectedVerification: str(form, "expectedVerification"), author: str(form, "author"), recordedAt: new Date().toISOString() }; updateRelease(data, release.id, (current) => ({ ...current, changelogs: [...(current.changelogs ?? []).filter((item) => item.componentChangeId !== componentChangeId), entry] })); close(); }; return <Dialog title="チェンジログを記載" close={close}><form onSubmit={save}><Choice label="対象変更" name="change" options={changes.map((change) => [change.id, `${component(data, change.componentId)?.name} · ${change.summary}`])} /><Choice label="記載元" name="source" options={[["manual", "手書き"], ["github-release", "GitHub Release"]]} /><Input label="変更内容" name="summary" /><Input label="利用者・システムへの影響" name="impact" /><Input label="互換性への影響" name="compatibility" /><Input label="想定する検証" name="expectedVerification" /><Input label="記載者" name="author" /><Save /></form></Dialog>; }
function ManualEvidenceForm({ release, close }: { release: Release; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const verificationId = str(form, "verification"); updateRelease(data, release.id, (current) => ({ ...current, verifications: current.verifications.map((verification) => { if (verification.id !== verificationId) return verification; const change = getChanges(current).find((item) => item.id === verification.componentChangeId); const pullRequest = change?.pullRequests[0]; const evidence = { id: id<"VerificationEvidence">(crypto.randomUUID()), type: str(form, "type") as keyof typeof verificationEvidenceTypeText, source: "manual" as const, repository: pullRequest?.repository ?? "manual", revision: str(form, "revision"), name: str(form, "name"), result: str(form, "result") as "passed" | "failed", observedAt: new Date().toISOString(), url: str(form, "url") || undefined }; const next = { ...verification, evidence: [...(verification.evidence ?? []), evidence] }; return { ...next, status: evidence.result === "failed" ? "failed" : verificationAssessment(current, next).state === "sufficient" ? "passed" : "running" }; }) })); close(); }; const first = release.verifications[0]; const firstChange = getChanges(release).find((item) => item.id === first?.componentChangeId); return <Dialog title="手動検証の証跡を登録" close={close}><form onSubmit={save}><Choice label="検証項目" name="verification" options={release.verifications.map((item) => [item.id, item.name])} /><Choice label="証跡種別" name="type" options={Object.entries(verificationEvidenceTypeText)} /><Input label="検証名" name="name" /><Input label="対象revision" name="revision" value={firstChange?.pullRequests[0]?.revision} /><Choice label="結果" name="result" options={[["passed", "成功"], ["failed", "失敗"]]} /><Input label="証跡URL" name="url" value="https://" /><Save /></form></Dialog>; }

const verificationReviewText: Record<VerificationReview["verdict"], string> = { adequate: "検証計画は変更内容と整合しています", "needs-review": "担当チームによる検証計画の見直しが必要です" };
async function requestVerificationReview(release: Release): Promise<VerificationReview> { const response = await fetch("/api/jev/review-verification", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ release: { code: release.code, name: release.name }, changes: getChanges(release).map((change) => ({ id: change.id, summary: change.summary, migration: change.migration, recovery: change.recovery, revision: change.pullRequests[0]?.revision })), changelogs: release.changelogs ?? [], verificationPlans: release.verifications.map((verification) => ({ name: verification.name, method: verification.method, successCriteria: verification.successCriteria, executionCondition: verification.condition, requiredTraceTypes: verification.requiredEvidenceTypes ?? [], resultState: verificationAssessment(release, verification).state })) }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(typeof body.error === "string" ? body.error : `Jev API request failed (${response.status})`); return body as VerificationReview; }

function ApprovalEligibilityPanel({ release, selectedPlan, evaluation, eligibility, approval, requestApproval }: { release: Release; selectedPlan?: PlanCandidate; evaluation?: JevPlanEvaluation; eligibility: ReturnType<typeof approvalEligibility>; approval: ApprovalStatus; requestApproval: () => void }) {
  return <section className={`approval-gate ${eligibility.canRequest ? "ready" : "blocked"}`}><div><span className="eyebrow">承認申請判定</span><h2>{eligibility.canRequest ? "承認申請できます" : "承認申請できません"}</h2><p>{evaluation ? `${selectedPlan?.name} · リスク ${evaluation.riskScore}/5 · confidence ${Math.round(evaluation.confidence * 100)}%` : "現在の実行計画に対する評価がありません。"}</p></div><div className="approval-reasons">{eligibility.blockers.length > 0 && <section><b>申請前に解決してください</b><ul>{eligibility.blockers.map((blocker) => <li key={blocker}>{blocker}</li>)}</ul></section>}{eligibility.commitments.length > 0 && <section><b>承認後に守る制約</b><ul>{eligibility.commitments.map((commitment) => <li key={commitment}>{commitment}</li>)}</ul></section>}</div>{evaluation ? <button className="primary" onClick={requestApproval} disabled={!eligibility.canRequest || approval === "pending"}>{approval === "pending" ? "承認申請済み" : "この計画で承認申請"}</button> : <Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画へ</Link>}</section>;
}

function ApprovalSchedule({ release }: { release: Release }) { const data = useData(); const scheduledAt = release.scheduledAt ?? `${release.scheduledFor}T10:00`; const approval = release.approvalStatus ?? "not-requested"; const revision = graphRevision(release); const evaluation = release.planDecision?.graphRevision === revision && release.planDecision.evaluation?.selectedPlanId === release.planDecision.selectedPlanId ? release.planDecision.evaluation : undefined; const selectedPlan = release.planDecision?.candidates.find((candidate) => candidate.id === release.planDecision?.selectedPlanId); const eligibility = approvalEligibility(release, evaluation); const requestApproval = () => { if (!eligibility.canRequest) return; updateRelease(data, release.id, (current) => ({ ...current, approvalStatus: "pending", approvedPlanRevision: revision, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "approval", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "実行計画の承認を申請", detail: `${selectedPlan?.name} · ${revision}` }] })); };
  const saveSchedule = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const nextAt = str(f, "scheduledAt"); const actor = str(f, "actor"); const record = f.get("recordHistory") === "on"; updateRelease(data, release.id, (current) => { const updated: Release = { ...current, scheduledAt: nextAt, scheduledFor: nextAt.slice(0, 10), considerations: str(f, "considerations"), notes: str(f, "notes"), history: record ? [...releaseHistory(current), { id: id<"ReleaseHistoryEntry">(crypto.randomUUID()), type: "schedule", occurredAt: new Date().toISOString(), actor, summary: `リリース予定を${dateTimeText(nextAt)}へ変更`, detail: `${dateTimeText(current.scheduledAt ?? `${current.scheduledFor}T10:00`)}から変更` }] : current.history }; return nextAt === (current.scheduledAt ?? `${current.scheduledFor}T10:00`) ? updated : invalidatePlan(updated, "リリース予定日時が変更されました"); }); };
  const saveApproval = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const nextStatus = str(f, "approvalStatus") as ApprovalStatus; if (["approved", "conditionally-approved"].includes(nextStatus) && !eligibility.canRequest) return alert("申請前の未解決事項を解消してください。"); const actor = str(f, "actor"); const note = str(f, "approvalNote"); const record = f.get("recordHistory") === "on"; updateRelease(data, release.id, (current) => ({ ...current, approvalStatus: nextStatus, approvedBy: actor, approvedPlanRevision: evaluation ? revision : current.approvedPlanRevision, planVersions: ["approved", "conditionally-approved"].includes(nextStatus) && evaluation ? (current.planVersions ?? []).map((version) => version.graphRevision === revision && version.status === "candidate" ? { ...version, status: "approved" as const } : version.status === "approved" ? { ...version, status: "superseded" as const } : version) : current.planVersions, history: record ? [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "approval", occurredAt: new Date().toISOString(), actor, summary: `承認状態を「${approvalText[nextStatus]}」へ変更`, detail: `${note}${evaluation ? ` · ${revision}` : ""}` }] : current.history })); };
  return <section className="approval-view"><div className="view-head"><div><span className="eyebrow">予定変更と承認履歴</span><h1>承認・予定</h1></div><div className="approval-current"><span className={`approval-state ${approval}`}>{approvalText[approval]}</span><b>{dateTimeText(scheduledAt)}</b></div></div><ApprovalEligibilityPanel release={release} selectedPlan={selectedPlan} evaluation={evaluation} eligibility={eligibility} approval={approval} requestApproval={requestApproval} /><div className="approval-layout"><div className="approval-forms"><form className="release-control-form" onSubmit={saveSchedule}><header><div><span>リリース予定</span><h2>{dateTimeText(scheduledAt)}</h2></div><small>実行計画の基準時刻</small></header><label>予定日時<input name="scheduledAt" type="datetime-local" defaultValue={scheduledAt} required /></label><label>考慮事項<textarea name="considerations" defaultValue={release.considerations ?? "モバイル審査通過後に段階配信を開始。旧APIは100%到達まで維持。"} /></label><label>備考<textarea name="notes" defaultValue={release.notes ?? ""} placeholder="日程調整の背景や関係者への連絡事項" /></label><Input label="変更者" name="actor" value="Taross K." /><label className="history-option"><input name="recordHistory" type="checkbox" defaultChecked /><span><b>変更履歴に残す</b><small>入力訂正など、監査対象にしない変更では外せます。</small></span></label><button className="primary" type="submit">予定を保存</button></form><form className="release-control-form" onSubmit={saveApproval}><header><div><span>承認状態</span><h2>{approvalText[approval]}</h2></div><small>{release.approvedBy ? `最終更新: ${release.approvedBy}` : "承認者未登録"}</small></header><Choice label="変更後の承認状態" name="approvalStatus" value={approval} options={[["pending", "承認待ち"], ["approved", "承認済み"], ["conditionally-approved", "条件付き承認"], ["rejected", "差し戻し"], ["not-requested", "未申請"]]} /><Input label="承認・変更者" name="actor" value={release.approvedBy ?? "田中 健"} /><label>判断理由・差し戻し内容<textarea name="approvalNote" placeholder="承認条件または差し戻し理由" /></label><label className="history-option"><input name="recordHistory" type="checkbox" defaultChecked /><span><b>変更履歴に残す</b><small>単なる操作ミスの訂正では外せます。</small></span></label><button className="primary" type="submit">承認状態を保存</button></form></div><aside className="release-history"><span className="eyebrow">変更履歴</span><h2>{releaseHistory(release).length}件</h2>{[...releaseHistory(release)].reverse().map((entry) => <article key={entry.id}><i className={`history-type ${entry.type}`} /><div><header><b>{entry.summary}</b><time>{dateTimeText(entry.occurredAt)}</time></header><span>{entry.actor}</span>{entry.detail && <p>{entry.detail}</p>}</div></article>)}</aside></div></section>; }

function TeamList() { const data = useData(); const [editing, setEditing] = useState<Team | "new" | null>(null); const remove = (target: Team) => { if (data.components.some((item) => item.ownerTeamId === target.id) || data.releases.some((item) => item.ownerTeamId === target.id)) return alert("使用中のチームは削除できません。"); if (confirm(`${target.name}を削除しますか？`)) data.setTeams((items) => items.filter((item) => item.id !== target.id)); }; return <section className="collection-view"><CollectionHeader count={data.teams.length} title="チーム" action="チームを登録" onAction={() => setEditing("new")} /><div className="settings-table"><div className="settings-head team-columns with-actions"><span>チーム名</span><span>責任者</span><span>メンバー</span><span>担当コンポーネント</span><span /></div>{data.teams.map((item) => <div className="settings-row team-columns with-actions" key={item.id}><b>{item.name}</b><span>{item.lead}</span><span>{item.memberCount}名</span><span>{data.components.filter((c) => c.ownerTeamId === item.id).map((c) => c.name).join("、") || "未設定"}</span><Actions edit={() => setEditing(item)} remove={() => remove(item)} /></div>)}</div>{editing && <TeamForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>; }
function TeamForm({ target, close }: { target?: Team; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const next: Team = { id: target?.id ?? id(crypto.randomUUID()), name: str(f, "name"), lead: str(f, "lead"), memberCount: Number(f.get("members")) }; data.setTeams((items) => target ? items.map((item) => item.id === target.id ? next : item) : [...items, next]); close(); }; return <Dialog title={target ? "チームを編集" : "チームを登録"} close={close}><form onSubmit={save}><Input label="チーム名" name="name" value={target?.name} /><Input label="責任者" name="lead" value={target?.lead} /><Input label="メンバー数" name="members" type="number" value={String(target?.memberCount ?? 0)} /><Save /></form></Dialog>; }

function ComponentList() { const data = useData(); const [editing, setEditing] = useState<Component | "new" | null>(null); const remove = (target: Component) => { if (data.releases.some((release) => getChanges(release).some((change) => change.componentId === target.id))) return alert("リリースで使用中のコンポーネントは削除できません。"); if (confirm(`${target.name}を削除しますか？`)) data.setComponents((items) => items.filter((item) => item.id !== target.id)); }; return <section className="collection-view"><CollectionHeader count={data.components.length} title="コンポーネント" action="コンポーネントを登録" onAction={() => setEditing("new")} /><div className="settings-table"><div className="settings-head component-columns with-actions"><span>名称</span><span>種別</span><span>担当チーム</span><span>GitHubリポジトリ</span><span>反映方法</span><span /></div>{data.components.map((item) => <div className="settings-row component-columns with-actions" key={item.id}><b>{item.name}</b><span>{kindText(item.kind)}</span><span>{team(data, item.ownerTeamId)?.name}</span><span className="repository-cell"><a href={item.repositoryUrl ?? `https://github.com/${item.repository}`} target="_blank" rel="noreferrer">{item.repository}</a><small>モック接続 · {item.defaultBranch ?? "main"}</small></span><span>{item.deliveryMethod}</span><Actions edit={() => setEditing(item)} remove={() => remove(item)} /></div>)}</div>{editing && <ComponentForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>; }
function ComponentForm({ target, close }: { target?: Component; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const repository = str(f, "repository"); const next: Component = { id: target?.id ?? id(crypto.randomUUID()), name: str(f, "name"), kind: str(f, "kind") as ComponentKind, ownerTeamId: id(str(f, "team")), repository, repositoryUrl: str(f, "repositoryUrl") || `https://github.com/${repository}`, defaultBranch: str(f, "defaultBranch"), githubConnection: "mock", deliveryMethod: str(f, "delivery") }; data.setComponents((items) => target ? items.map((item) => item.id === target.id ? next : item) : [...items, next]); close(); }; return <Dialog title={target ? "コンポーネントを編集" : "コンポーネントを登録"} close={close}><form onSubmit={save}><Input label="名称" name="name" value={target?.name} /><Choice label="種別" name="kind" value={target?.kind} options={[["ios", "iOSアプリ"], ["android", "Androidアプリ"], ["backend", "バックエンド"], ["admin", "Webアプリ"]]} /><Choice label="担当チーム" name="team" value={target?.ownerTeamId} options={data.teams.map((item) => [item.id, item.name])} /><Input label="GitHubリポジトリ（owner/name）" name="repository" value={target?.repository} /><Input label="GitHub URL" name="repositoryUrl" type="url" value={target?.repositoryUrl ?? (target?.repository ? `https://github.com/${target.repository}` : "")} /><Input label="デフォルトブランチ" name="defaultBranch" value={target?.defaultBranch ?? "main"} /><Input label="反映方法" name="delivery" value={target?.deliveryMethod} /><div className="connection-note"><b>接続方式</b><span>GitHubモック。実API接続時はGitHub AppのInstallation IDを保存します。</span></div><Save /></form></Dialog>; }

function JevRiskDemo({ release, close }: { release: Release; close: () => void }) {
  const data = useData(); const [state, setState] = useState<"idle" | "running" | "done">("idle"); const changes = getChanges(release);
  const migrations = changes.filter((item) => item.migration.required); const blocking = migrations.filter((item) => item.migration.execution === "blocking"); const unknown = changes.filter((item) => item.maintenance === "undetermined"); const missingRecovery = changes.filter((item) => !item.recovery.trim()); const mobile = changes.filter((item) => ["ios", "android"].includes(component(data, item.componentId)?.kind ?? ""));
  const hardIssues = unknown.length + missingRecovery.length + (hasCycle(changes) ? 1 : 0); const riskScore = Math.min(5, 1.4 + migrations.length * .55 + blocking.length * 1.2 + mobile.length * .25 + hardIssues * 1.3); const stagedProbability = hardIssues ? .38 : .86; const proceedProbability = hardIssues ? .31 : .88;
  const run = () => { setState("running"); window.setTimeout(() => setState("done"), 650); };
  return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal jev-demo"><button className="panel-close" onClick={close}>×</button><div className="jev-heading"><span className="demo-badge">モック判定 · API未接続</span><h2>Jevリスク判定</h2><p>実際のJev出力を模した型付き判定です。値はデモ用で、リリース判断には使用しません。</p></div><div className="jev-flow">
    <section><span className="step-number">01</span><div><h3>入力状態</h3><dl className="jev-input"><div><dt>コンポーネント変更</dt><dd>{changes.length}件</dd></div><div><dt>依存関係</dt><dd>{changes.reduce((sum, item) => sum + item.dependencyIds.length, 0)}件</dd></div><div><dt>migration</dt><dd>{migrations.length}件</dd></div><div><dt>blocking migration</dt><dd>{blocking.length}件</dd></div><div><dt>モバイル配布</dt><dd>{mobile.length}件</dd></div><div><dt>停止要否未判定</dt><dd>{unknown.length}件</dd></div></dl></div></section>
    <section><span className="step-number">02</span><div><h3>Jevへの型付き質問</h3><div className="typed-question"><b>choice</b><span>推奨する公開方式</span><code>段階公開 / メンテナンスモード / サービス停止</code></div><div className="typed-question"><b>score</b><span>リリースリスク</span><code>1（低）〜 5（高）</code></div><div className="typed-question"><b>yes / no</b><span>現在の計画で進行可能か</span><code>確率とconfidence</code></div></div></section>
    {state === "idle" && <button className="primary jev-run" onClick={run}>モック判定を実行</button>}{state === "running" && <div className="jev-running"><i />型付き判定を実行中</div>}{state === "done" && <><section><span className="step-number">03</span><div><h3>Jev出力（モック）</h3><DecisionBar label="段階公開" value={stagedProbability} selected /><DecisionBar label="メンテナンスモード" value={hardIssues ? .44 : .1} /><DecisionBar label="サービス停止" value={hardIssues ? .18 : .04} /><div className="score-output"><span>リスクスコア</span><b>{riskScore.toFixed(1)} / 5</b></div><div className="score-output"><span>進行可能</span><b>{Math.round(proceedProbability * 100)}%</b></div></div></section><section><span className="step-number">04</span><div><h3>ルールエンジンによる再検証</h3><div className={`rule-result ${hardIssues ? "failed" : "passed"}`}><b>{hardIssues ? "計画を確定できません" : "必須制約を満たしています"}</b><span>{hardIssues ? `未解決項目 ${hardIssues}件。Jevの推奨よりルール違反を優先します。` : "循環依存、停止要否未判定、回復方法の欠落はありません。"}</span></div></div></section><section><span className="step-number">05</span><div><h3>アプリケーションの判断</h3><div className="final-decision"><span>{hardIssues ? "保留" : "推奨"}</span><b>{hardIssues ? "未解決項目を修正後に再判定" : "停止なしで段階公開"}</b><p>{hardIssues ? "型付き判定だけでGo/No-Goを決めません。" : "バックエンドを先行し、検証後にモバイルを段階公開します。"}</p></div></div></section></>}
  </div><footer className="jev-footnote">Early Access取得後は、同じ入力・質問スキーマをサーバー側アダプターからJevへ送信します。</footer></section></div>;
}

function DecisionBar({ label, value, selected }: { label: string; value: number; selected?: boolean }) { return <div className={`decision-bar ${selected ? "selected" : ""}`}><span>{label}</span><i><em style={{ width: `${value * 100}%` }} /></i><b>{Math.round(value * 100)}%</b></div>; }

function CollectionHeader({ count, title, action, onAction }: { count: number; title: string; action?: string; onAction?: () => void }) { return <div className="view-head"><div><span className="eyebrow">全 {count}件</span><h1>{title}</h1></div>{action && <button className="primary" onClick={onAction}>＋ {action}</button>}</div>; }
function Actions({ edit, remove }: { edit: () => void; remove: () => void }) { return <span className="row-actions"><button onClick={(event) => { event.preventDefault(); event.stopPropagation(); edit(); }}>編集</button><button className="danger" onClick={(event) => { event.preventDefault(); event.stopPropagation(); remove(); }}>削除</button></span>; }
function Dialog({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal form-modal"><button className="panel-close" onClick={close}>×</button><h2>{title}</h2>{children}</section></div>; }
function Input({ label, name, value, type = "text" }: { label: string; name: string; value?: string; type?: string }) { return <label>{label}<input name={name} type={type} defaultValue={value} required /></label>; }
function Choice({ label, name, value, options }: { label: string; name: string; value?: string; options: [string, string][] }) { return <label>{label}<select name={name} defaultValue={value}>{options.map(([key, text]) => <option value={key} key={key}>{text}</option>)}</select></label>; }
function Save() { return <button className="primary form-submit" type="submit">保存</button>; }
function Empty({ text }: { text: string }) { return <div className="empty-state"><p>{text}</p></div>; }
function NotFound() { return <div className="empty-state"><p>対象が見つかりません</p><Link className="primary" to="/releases">リリース一覧へ</Link></div>; }

