const shortDateTime = (value: Date) => new Intl.DateTimeFormat("ja-JP", { month: "numeric", day: "numeric" }).format(value);
function timelineRange(transitions: VersionTransition[]) { if (!transitions.length) { const now = Date.now(); return { start: now, end: now + 24 * 60 * 60 * 1000 }; } const starts = transitions.map((item) => new Date(item.startsAt).getTime()); const ends = transitions.map((item) => new Date(item.expectedCompletionAt).getTime()); return { start: Math.min(...starts) - 12 * 60 * 60 * 1000, end: Math.max(...ends) + 12 * 60 * 60 * 1000 }; }
function percentAt(value: string, range: { start: number; end: number }) { return Math.max(0, Math.min(100, ((new Date(value).getTime() - range.start) / (range.end - range.start)) * 100)); }
function releasePlanRisks(data: Store, release: Release, groups: ComponentChangeGroup[]) { const risks: { level: "low" | "medium" | "high"; scope: string; title: string; body: string; control: string }[] = []; const mobile = groups.filter((group) => ["ios", "android"].includes(group.component.kind)); const backend = groups.find((group) => group.component.kind === "backend"); const mobileCompletion = Math.max(...mobile.map((group) => new Date(versionTransition(group.changes[0], group.component, release).expectedCompletionAt).getTime()), 0); mobile.forEach((group) => { const transition = versionTransition(group.changes[0], group.component, release); risks.push({ level: transition.coexistence === "incompatible" ? "high" : "medium", scope: group.component.name, title: "新旧バージョンの同時稼働", body: `${dateTimeText(transition.startsAt)}から${dateTimeText(transition.expectedCompletionAt)}まで旧版利用者が残ります。`, control: transition.coexistence === "feature-flag" ? "新APIはFeature Flagで有効化し、旧APIを維持" : "互換APIとversion別メトリクスを維持" }); }); if (mobile.length) risks.push({ level: "high", scope: "iOS・Android", title: "即時rollback不可", body: "ストア配布後のクライアントバイナリはサーバーのように一括で旧版へ戻せません。", control: "Feature Flagで機能停止し、修正版配布まで旧APIを維持" }); if (backend?.changes.some((change) => change.migration.required)) risks.push({ level: "medium", scope: backend.component.name, title: "contract migrationの実行時期", body: "旧クライアントが参照するschemaを段階配信中に削除できません。", control: mobileCompletion ? `モバイル100%到達後の${dateText(new Date(mobileCompletion + 86400000).toISOString().slice(0, 10))}以降を実行条件に設定` : "依存クライアントの利用終了を実行条件に設定" }); if (mobile.length) risks.push({ level: "medium", scope: "配信監視", title: "到達率は予定値", body: "審査時間と利用者の更新状況により100%到達時刻は変動します。", control: "バージョン別エラー率が2%を超えた場合は配信を停止" }); groups.forEach((group) => group.changes.filter((change) => change.maintenance === "undetermined" || !change.recovery.trim()).forEach((change) => risks.push({ level: "high", scope: group.component.name, title: change.maintenance === "undetermined" ? "停止要否が未判定" : "回復方法が未登録", body: change.summary, control: "実行計画の確定前に担当チームが登録" }))); if (hasCycle(getChanges(release))) risks.push({ level: "high", scope: "コンポーネント間依存", title: "循環依存", body: "依存関係から実行順序を確定できません。", control: "依存を分割するかFeature Flagで有効化順を分離" }); return risks; }
